def dossier_image_classee(racine, format_image, largeur, hauteur):
    """
    Retourne automatiquement le dossier correspondant
    au format et aux dimensions exactes de l'image.

    Exemple :
        BMP 32x32   -> BMP/32x32
        BMP 256x128 -> BMP/256x128
        DDS 640x448 -> DDS/640x448
        ICO 16x16   -> ICO/16x16
    """
    format_image = str(format_image).upper()

    dossier = racine / format_image

    if largeur > 0 and hauteur > 0:
        dossier = dossier / f"{largeur}x{hauteur}"

    return dossier


def chemin_image_classee(racine, format_image, largeur, hauteur, nom):
    """Construit le chemin complet d'une image classée."""
    return dossier_image_classee(
        racine, format_image, largeur, hauteur
    ) / nom


def creer_dossiers_images(racine):
    """
    Crée uniquement les dossiers principaux des formats.

    Les sous-dossiers de dimensions sont créés automatiquement
    lorsqu'une image est réellement rencontrée.
    """
    for format_image in FORMATS_IMAGES:
        (racine / format_image).mkdir(
            parents=True,
            exist_ok=True
        )


def creer_marqueur_backup_disable(
    data_version,
    langue
):
    """
    Crée dans le Data PC injecté un fichier marqueur propre à la langue afin d'empêcher qu'une version déjà modifiée soit reprise comme sauvegarde originale.
    
    Paramètres:
        data_version, langue.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : aucune autre fonction interne directe détectée.
    """
    langue = langue.lower()

    nom = MARQUEURS_BACKUP_DISABLE.get(
        langue
    )

    if nom is None:
        raise RuntimeError(
            f"Langue inconnue : {langue}"
        )

    marqueur = (
        Path(data_version)
        / nom
    )

    contenu = (
        "BACKUP PC INTERDIT\n"
        "\n"
        "Ce dossier Data contient une version modifiee "
        "par l'utilitaire de localisation.\n"
        "\n"
        "NE PAS utiliser ce dossier comme backup original.\n"
        "\n"
        "Pour recreer un backup valide :\n"
        "1. Reinstaller/restaurer le jeu original avec PC.\n"
        "2. Verifier que le dossier Data est propre.\n"
        "3. Relancer l'utilitaire.\n"
        "4. Laisser l'utilitaire creer un nouveau VERSION_BACKUP.\n"
    )

    marqueur.write_text(
        contenu,
        encoding="utf-8"
    )

    print(
        "[GARDE-FOU] Marqueur cree :",
        marqueur.name
    )


def calculer_ratio_proximite(texte_a, texte_b):
    """
    Calcule ratio proximite.
    
    Paramètres:
        texte_a, texte_b.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : aucune autre fonction interne directe détectée.
    """
    return SequenceMatcher(None, texte_a, texte_b).ratio()


def construire_memoire_jam_globale(jam_root_pc, ps2_index):
    """
    Construit la mémoire globale de correspondances textuelles JAM entre les données PC et les sources PS2_VERSION.
    
    Paramètres:
        jam_root_pc, ps2_index.
    
    Connexions:
        Appelée par : traduire_tous_jam_localises.
        Appelle : blocs_texte, choisir_bloc_structurel, normaliser_texte_jam, parse_chaines_multiples, score_langue, trouver_ps2_jam, variables_texte_jam.
    """
    candidats_cles = {}
    candidats_textes = {}
    fichiers_paires = 0

    # 1. Indexation globale de toutes les clés/valeurs de la PS2_VERSION
    fichiers_ps2 = sorted(
        {fichier
         for liste in ps2_index.values()
         for fichier in sorted(liste)})

    for fichier in fichiers_ps2:
        try:
            for bloc in blocs_texte(fichier.read_bytes()):
                for cle, valeurs in parse_chaines_multiples(
                        bloc["payload"]).items():
                    candidats_cles.setdefault(cle, set()).update(valeurs)
        except Exception:
            continue

    # 2. Construction de la mémoire sémantique (Texte Anglais PC -> Texte FR PS2_VERSION)
    for pc in sorted(jam_root_pc.rglob("*.JAM")):
        relatif = pc.relative_to(jam_root_pc)
        ps2 = trouver_ps2_jam(relatif, ps2_index)

        if ps2 is None:
            continue

        fichiers_paires += 1
        try:
            blocs_pc = blocs_texte(pc.read_bytes())
            blocs_ps2 = blocs_texte(ps2.read_bytes())
        except Exception:
            continue

        for bloc_pc in blocs_pc:
            candidats = [
                bloc for bloc in blocs_ps2
                if bloc["namespace"] == bloc_pc["namespace"]
            ]
            bloc_ps2 = choisir_bloc_structurel(bloc_pc["payload"], candidats)

            if bloc_ps2 is None:
                continue

            valeurs_pc = parse_chaines_multiples(bloc_pc["payload"])
            valeurs_ps2 = parse_chaines_multiples(bloc_ps2["payload"])

            for cle, liste_pc in valeurs_pc.items():
                liste_ps2 = valeurs_ps2.get(cle, ())

                for valeur_pc, valeur_ps2 in zip(liste_pc, liste_ps2):
                    # Sécurité : on n'associe que si les variables techniques correspondent
                    if variables_texte_jam(valeur_pc) != variables_texte_jam(
                            valeur_ps2):
                        continue
                    if valeur_pc == valeur_ps2:
                        continue

                    normalisee = normaliser_texte_jam(valeur_pc)
                    if normalisee:
                        candidats_textes.setdefault(normalisee,
                                                    set()).add(valeur_ps2)

    # 3. Filtrage et nettoyage pour ne garder que les valeurs les plus sûres
    cles_sures = {
        cle: tuple(sorted(valeurs))
        for cle, valeurs in candidats_cles.items()
    }

    # Pour le dictionnaire de secours sémantique (par texte), on prend la traduction
    # qui obtient le meilleur score de la langue cible
    textes_surs = {}
    for texte_en, valeurs_fr in candidats_textes.items():
        if len(valeurs_fr) == 1:
            textes_surs[texte_en] = next(iter(valeurs_fr))
        else:
            # En cas de traductions multiples pour une même phrase anglaise,
            # on élit celle qui a le meilleur score linguistique
            meilleure_valeur = max(
                valeurs_fr,
                key=lambda v: score_langue({"KEY": v}, LANGUE_CIBLE))
            textes_surs[texte_en] = meilleure_valeur

    print(f"[MEMOIRE JAM] {fichiers_paires} fichiers couples | "
          f"{len(cles_sures)} cles globales | "
          f"{len(textes_surs)} phrases de secours (Fallback) indexees.")

    return cles_sures, textes_surs


def generer_ecran_sierra_localise(langue_cible="fr"):
    """
    Génère ecran sierra localise.
    
    Paramètres:
        langue_cible.
    
    Connexions:
        Appelée par : construire_version_fr, injecter_langue_ps2.
        Appelle : normaliser_code_langue, sha256, supprimer.
    """
    langue_cible = normaliser_code_langue(langue_cible)

    images_par_langue = {
        "fr": BASE64_IMG_FR_ALLRIGHT_SIERRA,
        "en": BASE64_IMG_EN_ALLRIGHT_SIERRA,
        "de": BASE64_IMG_DE_ALLRIGHT_SIERRA,
        "es": BASE64_IMG_ES_ALLRIGHT_SIERRA,
        "it": BASE64_IMG_IT_ALLRIGHT_SIERRA,
    }

    empreintes_attendues = {
        "fr":
        "3f8f38cff0d0d5c1f16eb5d17874a8501dfc9ca1fbcddaea717fe735708e903b",
        "en":
        "5d050df701352d0a97c9cf37fdfd1c484689b4ed7805311ac8ad5ebb4a7075f5",
        "de":
        "95ad554df401fbbdc9d820a0f13e477910562773c55ad719af3e96dc6521a1cb",
        "es":
        "56cff9cd79aadb88131bac06a924646555d468a525ccd76a203c7c93b904b3f6",
        "it":
        "80a99460f10ec721c24c60ad845bdfe0d53e80026eeb4de795e0cb4e4473e7d7",
    }

    image_base64 = images_par_langue.get(langue_cible)

    if image_base64 is None:
        print("[SIERRA] Aucune image integree pour la langue :", langue_cible)
        return False

    nom_image = ("IntrFram.JAM"
                 "__BMP"
                 "__0003"
                 "__00086C98"
                 "__512x512"
                 "__8bpp.bmp")

    destination = chemin_image_classee(
        IMAGE_INJECT, "BMP", 512, 512, nom_image
    )

    try:

        destination.parent.mkdir(parents=True, exist_ok=True)

        chaine = re.sub(r"\s+", "", image_base64)

        if not chaine:

            raise RuntimeError("Donnees Base64 Sierra absentes.")

        donnees_compressees = (base64.b64decode(chaine, validate=True))

        donnees_bmp = (zlib.decompress(donnees_compressees))

        if len(donnees_bmp) not in (
                262728,
                786486,
        ):

            raise RuntimeError("Taille BMP Sierra incorrecte : "
                               f"{len(donnees_bmp)} octets.")

        if not donnees_bmp.startswith(b"BM"):

            raise RuntimeError("Signature BMP Sierra invalide.")

        empreinte = hashlib.sha256(donnees_bmp).hexdigest()

        empreinte_attendue = empreintes_attendues[langue_cible]

        if empreinte != empreinte_attendue:

            raise RuntimeError("Empreinte Sierra incorrecte.")

        destination.write_bytes(donnees_bmp)

        print(f"[SIERRA {langue_cible.upper()}] Image generee :",
              destination.name)

        return True

    except Exception as erreur:

        print(f"[SIERRA {langue_cible.upper()} ERREUR]", erreur)

        supprimer(destination)

        return False


def installer_ffmpeg():
    """
    Installe ffmpeg.
    
    Connexions:
        Appelée par : assurer_outils.
        Appelle : supprimer, telecharger.
    """
    OUTILS.mkdir(parents=True, exist_ok=True)
    destination_ffmpeg = (OUTILS / "ffmpeg.exe")
    destination_ffprobe = (OUTILS / "ffprobe.exe")

    if destination_ffmpeg.exists() and destination_ffprobe.exists():

        print("[OUTIL OK] ffmpeg.exe et ffprobe.exe")

        return destination_ffmpeg

    manquants = []
    if not destination_ffmpeg.exists():
        manquants.append("ffmpeg.exe")
    if not destination_ffprobe.exists():
        manquants.append("ffprobe.exe")

    print("[OUTIL] Installation requise :", ", ".join(manquants))

    url = ("https://www.gyan.dev/ffmpeg/builds/"
           "ffmpeg-release-essentials.zip")

    archive = (ROOT / "_ffmpeg.zip")

    temp = (ROOT / "_ffmpeg_temp")

    try:

        telecharger(url, archive)

        supprimer(temp)

        temp.mkdir(parents=True)

        with zipfile.ZipFile(archive, "r") as zipf:

            zipf.extractall(temp)

        candidats_ffmpeg = list(temp.rglob("ffmpeg.exe"))
        candidats_ffprobe = list(temp.rglob("ffprobe.exe"))

        if not candidats_ffmpeg:

            raise RuntimeError("ffmpeg.exe absent de l'archive.")

        if not candidats_ffprobe:

            raise RuntimeError("ffprobe.exe absent de l'archive.")

        # Les deux exécutables doivent provenir de la même distribution.
        # ffprobe est indispensable pour sélectionner la piste audio SFD.
        shutil.copy2(candidats_ffmpeg[0], destination_ffmpeg)
        shutil.copy2(candidats_ffprobe[0], destination_ffprobe)

        print("[OUTILS INSTALLES]", destination_ffmpeg, "et",
              destination_ffprobe)

        return destination_ffmpeg

    finally:

        supprimer(archive)

        supprimer(temp)


def installer_afspacker():
    """
    Installe afspacker.
    
    Connexions:
        Appelée par : assurer_outils.
        Appelle : charger_module_local, supprimer, telecharger.
    """
    OUTILS.mkdir(parents=True, exist_ok=True)
    destination = (OUTILS / "AFSPacker.exe")

    if destination.exists():

        print("[OUTIL OK] AFSPacker.exe :", destination)

        return destination

    print("[OUTIL] AFSPacker.exe absent.")

    api = ("https://api.github.com/repos/"
           "MaikelChan/AFSPacker/"
           "releases/latest")

    requete = urllib.request.Request(api,
                                     headers={
                                         "User-Agent":
                                         "Larry-MCL-FR-All-In-One",
                                         "Accept":
                                         "application/vnd.github+json",
                                     })

    with urllib.request.urlopen(requete, timeout=60) as reponse:

        release = json.loads(reponse.read().decode("utf-8"))

    print("[AFSPACKER] Release :", release.get("tag_name", "?"))

    assets = release.get("assets", [])

    print("[AFSPACKER] Fichiers disponibles :")

    for asset in assets:

        print(" -", asset.get("name", "?"))

    # =========================================
    # RECHERCHE VERSION WINDOWS X64
    # =========================================

    asset_windows = None

    for asset in assets:

        nom = asset.get("name", "").lower()

        if ("win" in nom and "x64" in nom
                and (nom.endswith(".7z") or nom.endswith(".zip")
                     or nom.endswith(".exe"))):

            asset_windows = asset
            break

    if asset_windows is None:

        raise RuntimeError("Version Windows x64 "
                           "AFSPacker introuvable.")

    nom_asset = asset_windows["name"]

    url = asset_windows["browser_download_url"]

    print("[AFSPACKER] Selection :", nom_asset)

    archive = (ROOT / nom_asset)

    temp = (ROOT / "_AFSPACKER_TEMP")

    supprimer(temp)

    temp.mkdir(parents=True, exist_ok=True)

    try:

        telecharger(url, archive)

        # =====================================
        # EXE DIRECT
        # =====================================

        if (archive.suffix.lower() == ".exe"):

            shutil.copy2(archive, destination)

        # =====================================
        # ZIP
        # =====================================

        elif (archive.suffix.lower() == ".zip"):

            with zipfile.ZipFile(archive, "r") as zipf:

                zipf.extractall(temp)

        # =====================================
        # 7Z
        # =====================================

        elif (archive.suffix.lower() == ".7z"):

            py7zr = charger_module_local("py7zr", "py7zr")

            with py7zr.SevenZipFile(archive, mode="r") as septzip:

                septzip.extractall(path=temp)

        else:

            raise RuntimeError("Format AFSPacker inconnu : " + archive.suffix)

        # =====================================
        # COPIE DE TOUS LES FICHIERS
        # =====================================

        if temp.exists() and not destination.exists():

            executables = list(temp.rglob("AFSPacker.exe"))

            if not executables:

                raise RuntimeError("AFSPacker.exe absent "
                                   "de l'archive.")

            source_exe = (executables[0])

            shutil.copy2(source_exe, destination)

        if not destination.exists():

            raise RuntimeError("AFSPacker.exe "
                               "non installe.")

        print("[OUTIL INSTALLE]", destination)

        return destination

    finally:

        supprimer(archive)

        supprimer(temp)


def installer_sfd_muxer():
    """
    Installe sfd muxer.
    
    Connexions:
        Appelée par : assurer_outils.
        Appelle : installer_module_local.
    """
    OUTILS.mkdir(parents=True, exist_ok=True)
    exe_local = (OUTILS / "sfd-muxer.exe")

    # =========================================
    # VERIFICATION MODULE LOCAL
    # =========================================

    module_local = (VENDOR / "sfd_muxer")

    if (exe_local.exists() and module_local.exists()):

        print("[OUTIL OK] sfd-muxer local :", exe_local)

        return exe_local

    print("[OUTIL] Installation locale "
          "de SFD Muxer...")

    # =========================================
    # INSTALLATION DU MODULE DANS _vendor
    # =========================================

    installer_module_local("sfd-muxer")

    # =========================================
    # CREATION / RECUPERATION DU LAUNCHER
    # =========================================

    scripts = (Path(sys.executable).parent / "Scripts")

    candidats = (list(scripts.glob("sfd-muxer*.exe")) +
                 list(scripts.glob("sfd_muxer*.exe")))

    if candidats:

        shutil.copy2(candidats[0], exe_local)

        print("[OUTIL INSTALLE]", exe_local)

        return exe_local

    # Le module est quand meme installe
    # localement et utilisable depuis Python.
    print("[SFD] Module Python local installe :", module_local)

    return module_local


def installer_sfd_muxer_original():
    """
    Installe sfd muxer original.
    
    Connexions:
        Appelée par : assurer_outils.
        Appelle : supprimer, telecharger.
    """
    OUTILS.mkdir(parents=True, exist_ok=True)
    destination = (OUTILS / "SFD_Muxer.exe")

    if destination.exists():

        print("[OUTIL OK] SFD_Muxer C :", destination)

        return destination

    print("[OUTIL] Installation du "
          "SFD_Muxer C...")

    api = ("https://api.github.com/repos/"
           "Firebow59/SofdecVideoTools/"
           "releases/latest")

    requete = urllib.request.Request(api,
                                     headers={
                                         "User-Agent":
                                         "Larry-MCL-FR-All-In-One",
                                         "Accept":
                                         "application/vnd.github+json",
                                     })

    with urllib.request.urlopen(requete, timeout=60) as reponse:

        release = json.loads(reponse.read().decode("utf-8"))

    print("[SFD C] Release :", release.get("tag_name", "?"))

    assets = release.get("assets", [])

    archives = []

    for asset in assets:

        nom = asset.get("name", "")

        url = asset.get("browser_download_url")

        if not url:
            continue

        nom_lower = nom.lower()

        if nom_lower.endswith(".zip"):

            archives.append((nom, url))

    if not archives:

        raise RuntimeError("Archive Windows "
                           "SofdecVideoTools introuvable.")

    # Preferer l'archive Windows si
    # plusieurs ZIP sont presentes.
    archives.sort(key=lambda item: (0 if ("win" in item[0].lower(
    ) or "windows" in item[0].lower()) else 1, item[0].lower()))

    nom_archive, url = (archives[0])

    print("[SFD C] Selection :", nom_archive)

    archive = (ROOT / "_sfd_tools.zip")

    temp = (ROOT / "_sfd_tools_temp")

    try:

        telecharger(url, archive)

        supprimer(temp)

        temp.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(archive, "r") as zipf:

            zipf.extractall(temp)

        candidats = list(temp.rglob("SFD_Muxer.exe"))

        if not candidats:

            candidats = list(temp.rglob("sfd_muxer.exe"))

        if not candidats:

            raise RuntimeError("SFD_Muxer.exe absent "
                               "de l'archive.")

        source_exe = (candidats[0])

        shutil.copy2(source_exe, destination)
        exe_final = destination

        print("[OUTIL INSTALLE]", exe_final)

        return exe_final

    finally:

        supprimer(archive)

        supprimer(temp)


def charger_module_local(nom_module, nom_pip=None):
    """
    Charge module local.
    
    Paramètres:
        nom_module, nom_pip.
    
    Connexions:
        Appelée par : installer_afspacker.
        Appelle : installer_module_local.
    """
    if nom_pip is None:
        nom_pip = nom_module

    try:

        return importlib.import_module(nom_module)

    except ImportError:

        print("[MODULE LOCAL]", nom_module, "absent.")

        installer_module_local(nom_pip)

        importlib.invalidate_caches()

        return importlib.import_module(nom_module)


def installer_module_local(module_pip):
    """
    Installe module local.
    
    Paramètres:
        module_pip.
    
    Connexions:
        Appelée par : charger_module_local, installer_sfd_muxer.
        Appelle : aucune autre fonction interne directe détectée.
    """
    VENDOR.mkdir(parents=True, exist_ok=True)

    print("[PYTHON LOCAL]", module_pip)

    commande_pip = [
        sys.executable,
        "-m",
        "pip",
        "install",
        "--upgrade",
        "--target",
        str(VENDOR),
        module_pip,
    ]

    resultat = subprocess.run(commande_pip)

    if resultat.returncode != 0:

        raise RuntimeError(f"Installation locale impossible : "
                           f"{module_pip}")

    # Important pour l'import immediat
    # pendant cette meme execution.
    if str(VENDOR) not in sys.path:

        sys.path.insert(0, str(VENDOR))

    return True


def copier_dossier(source, destination):
    """
    Copie dossier.
    
    Paramètres:
        source, destination.
    
    Connexions:
        Appelée par : construire_version_fr.
        Appelle : supprimer.
    """
    if destination.exists():
        supprimer(destination)

    destination.parent.mkdir(parents=True, exist_ok=True)

    shutil.copytree(source, destination)


def migrer_dossier_legacy(ancien, nouveau):
    """Migre un ancien dossier sans perdre son contenu."""
    source = next(
        (element for element in ancien.parent.iterdir()
         if element.name == ancien.name),
        None,
    )
    if source is None or source.name == nouveau.name:
        return

    if source.name.lower() == nouveau.name.lower():
        temporaire = nouveau.parent / f"__RENOMMAGE_{nouveau.name}"
        supprimer(temporaire)
        source.rename(temporaire)
        temporaire.rename(nouveau)
        return

    if not nouveau.exists():
        shutil.move(str(source), str(nouveau))
        return

    shutil.copytree(source, nouveau, dirs_exist_ok=True)
    supprimer(source)


def migrer_fichier_legacy(ancien, nouveau):
    """Déplace un ancien fichier vers son nouvel emplacement."""
    if ancien.exists() and not nouveau.exists():
        nouveau.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(ancien), str(nouveau))


