def sha256(data):
    """
    Calcule le SHA-256 de.
    
    Paramètres:
        data.
    
    Connexions:
        Appelée par : analyser_jam_detaille, diagnostiquer_localisation_ps2, empreinte_sha256, extraire_images, generer_ecran_sierra_localise, parcourir_afs.
        Appelle : aucune autre fonction interne directe détectée.
    """
    return hashlib.sha256(data).hexdigest()


def supprimer(path):
    """
    Supprime.
    
    Paramètres:
        path.
    
    Connexions:
        Appelée par : construire_version_fr, copier_dossier, copier_ps2_depuis_lecteur, encoder_audio_taille_pc, extraire_images, generer_ecran_sierra_localise, injecter_data_version_edit_fini, injecter_images_depuis_menu, injecter_langue_ps2, installer_afspacker, installer_ffmpeg, installer_sfd_muxer_original, localiser_cinema, muxer_sfd_robuste.
        Appelle : aucune autre fonction interne directe détectée.
    """
    if path.exists():

        if path.is_dir():

            def forcer_suppression(fonction, chemin, erreur):
                # Les fichiers copiés depuis un DVD/ISO héritent souvent de
                # l'attribut lecture seule. On ne modifie que la copie locale
                # qui doit être supprimée, jamais le disque source monté.
                """
                Force suppression.
                
                Paramètres:
                    fonction, chemin, erreur.
                
                Connexions:
                    Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
                    Appelle : aucune autre fonction interne directe détectée.
                """
                try:
                    os.chmod(chemin, stat.S_IWRITE
                             | stat.S_IREAD
                             | stat.S_IEXEC)
                    fonction(chemin)
                except Exception:
                    raise

            shutil.rmtree(path, onerror=forcer_suppression)
        else:
            try:
                os.chmod(path, stat.S_IWRITE | stat.S_IREAD)
            except OSError:
                pass
            path.unlink()


def detecter_ps2_monte():
    """
    Détecte ps2 monte.
    
    Connexions:
        Appelée par : preparer_ps2.
        Appelle : lister_lecteurs_windows, titre, trouver_entree_racine_ci, trouver_executable_ps2.
    """
    titre("DETECTION DU JEU PS2_VERSION")

    lecteurs = (lister_lecteurs_windows())

    if not lecteurs:

        print("Aucun lecteur detecte.")

        return None

    print("Lecteurs detectes :")

    for lecteur in lecteurs:

        print(" -", lecteur)

    print()
    print("Recherche d'un dossier DATA "
          "et d'un executable PS2_VERSION...")

    for lecteur in lecteurs:

        try:

            print("[SCAN JEU PC]", lecteur)

            data = trouver_entree_racine_ci(lecteur, "DATA")

            executable = trouver_executable_ps2(lecteur)

            if data is None:
                print("  -> DATA absent")
                continue

            if not data.is_dir():
                print("  -> DATA trouve mais "
                      "ce n'est pas un dossier :", data)
                continue

            if executable is None:
                print("  -> DATA present, mais "
                      "executable PS2_VERSION absent")
                continue

            print()
            print("[SCAN JEU PS2_VERSION] Executable detecte :")

            print(executable)

            print("[SCAN JEU PS2_VERSION] Dossier DATA detecte :")

            print(data)

            return lecteur

        except (PermissionError, OSError):

            continue

    return None


def copier_ps2_depuis_lecteur(lecteur):
    """
    Copie ps2 depuis lecteur.
    
    Paramètres:
        lecteur.
    
    Connexions:
        Appelée par : preparer_ps2.
        Appelle : supprimer, trouver_entree_racine_ci, trouver_executable_ps2.
    """
    source = trouver_entree_racine_ci(lecteur, "DATA")

    destination = PS2_VERSION

    if (source is None or not source.exists() or not source.is_dir()):

        raise RuntimeError(f"DATA PS2_VERSION introuvable : "
                           f"{source}")

    print()
    print("[SCAN JEU PS2_VERSION] Copie complete "
          "de la version source...")

    print("Source :", source)

    print("Destination :", destination)

    # On remplace uniquement notre dossier local PS2_VERSION, jamais le disque
    # monté. Toute la racine est conservée : DATA, LARRY.INI, SYSTEM.CNF,
    # SLES, IOPRP280.IMG, IRXBUNDL.IIB et les éventuels fichiers futurs.
    if destination.exists():
        supprimer(destination)

    shutil.copytree(lecteur, destination)

    executable = trouver_executable_ps2(lecteur)

    nom_executable = (executable.name.upper()
                      if executable is not None else None)

    edition = EDITIONS_PS2.get(nom_executable, {})

    profil_source = {
        "lecteur_source": str(lecteur),
        "executable_ps2": nom_executable,
        "langue_detectee": edition.get("langue"),
        "nom_langue": edition.get("nom"),
        "edition_connue": bool(edition),
        "priorite_actuelle": "fr",
        "edition_francaise": nom_executable == "SLES_526.42",
        "racine_disque": str(lecteur),
        "dossier_data": str(source),
        "copie_complete": True,
    }

    (PS2_VERSION / "SOURCE_PS2.json").write_text(json.dumps(profil_source,
                                                            ensure_ascii=False,
                                                            indent=2),
                                                 encoding="utf-8")

    print()
    print("[SCAN JEU PS2_VERSION] Copie terminee.")

    if executable is not None:
        print("[SCAN JEU PS2_VERSION] Version :", executable.name)

    if edition:
        print("[SCAN JEU PS2_VERSION] Langue detectee :", edition["nom"])

    if nom_executable != "SLES_526.42":
        print("[SCAN JEU PS2_VERSION] Information : les futurs tests multilingues sont "
              "prepares, mais la validation actuelle reste francaise.")

    return True


def preparer_ps2():
    """
    Prépare la source PS2.

    Ordre de priorité :

        1. Jeu PS2 monté.
        2. Copie locale PS2_VERSION déjà valide.
        3. Sélection manuelle d'une ISO non montée.
        4. Si aucune source :
           retourne False sans bloquer le programme.

    Connexions :
        Appelée par :
            initialiser
            main
            menu

        Utilise :
            detecter_ps2_monte
            trouver_executable_ps2
            copier_ps2_depuis_lecteur
            ps2_contient_donnees
            demander_iso_ps2
            LecteurISO9660
    """

    # =====================================================
    # 1. RECHERCHE D'UN JEU PS2 MONTE
    # =====================================================

    lecteur = detecter_ps2_monte()

    if lecteur is not None:

        executable_lecteur = trouver_executable_ps2(
            lecteur
        )

        executable_local = trouver_executable_ps2(
            PS2_VERSION
        )

        version_lecteur = (
            executable_lecteur.name.upper()
            if executable_lecteur is not None
            else None
        )

        version_locale = (
            executable_local.name.upper()
            if executable_local is not None
            else None
        )

        copie_valide = ps2_contient_donnees()

        # -------------------------------------------------
        # Même version déjà copiée
        # -------------------------------------------------

        if (
            copie_valide
            and version_lecteur == version_locale
        ):

            print(
                "[SCAN JEU PS2] "
                "Le disque monte correspond deja "
                "a la copie locale :",
                version_locale
            )

            return True

        # -------------------------------------------------
        # Une autre édition était présente localement
        # -------------------------------------------------

        if copie_valide:

            print(
                "[SCAN JEU PS2] "
                "Changement d'edition detecte :",
                version_locale,
                "->",
                version_lecteur
            )

        # -------------------------------------------------
        # Copier le nouveau disque PS2
        # -------------------------------------------------

        try:

            copier_ps2_depuis_lecteur(
                lecteur
            )

        except Exception as erreur:

            print(
                "[ERREUR PS2]",
                erreur
            )

            return False

        # -------------------------------------------------
        # Vérification après copie
        # -------------------------------------------------

        if ps2_contient_donnees():

            executable_local = trouver_executable_ps2(
                PS2_VERSION
            )

            print()
            print(
                "[SCAN JEU PS2] "
                "Jeu PS2 pret pour la conversion :",
                (
                    executable_local.name
                    if executable_local is not None
                    else "version inconnue"
                )
            )

            return True

    # =====================================================
    # 2. AUCUN DISQUE MONTE
    #    MAIS COPIE LOCALE DISPONIBLE
    # =====================================================

    if ps2_contient_donnees():

        executable_local = trouver_executable_ps2(
            PS2_VERSION
        )

        print()
        print(
            "[SCAN JEU PS2] "
            "Aucun disque monte detecte."
        )

        print(
            "[SCAN JEU PS2] "
            "Utilisation de la copie locale :",
            (
                executable_local.name
                if executable_local is not None
                else "version inconnue"
            )
        )

        return True

    # =====================================================
    # 3. AUCUNE SOURCE PS2
    #    PROPOSER UNE ISO NON MONTEE
    # =====================================================

    print()
    print(
        "[SCAN JEU PS2] "
        "Aucun jeu PS2 monte detecte."
    )

    print(
        "[SCAN JEU PS2] "
        "Aucune copie locale disponible."
    )

    print()
    print(
        "Vous pouvez selectionner directement "
        "une image ISO PS2."
    )

    iso = demander_iso_ps2()

    # =====================================================
    # 4. UTILISATEUR CLIQUE SUR ANNULER
    # =====================================================

    if iso is None:

        print()
        print("=" * 70)
        print("AUCUN JEU PS2 DETECTE")
        print("=" * 70)

        print()
        print(
            "Aucun disque PS2 monte "
            "et aucune ISO selectionnee."
        )

        print()
        print(
            "Le programme continue sans source PS2."
        )

        return False

    # =====================================================
    # 5. ISO SELECTIONNEE
    # =====================================================

    print()
    print(
        "[PS2 ISO] ISO selectionnee :"
    )

    print(
        iso
    )

    try:

        with LecteurISO9660(
            iso
        ) as lecteur_iso:

            # =============================================
            # DETECTION VERSION
            # =============================================

            version_iso = (
                lecteur_iso.detecter_version_ps2()
            )

            if not version_iso:

                print()
                print(
                    "[PS2 ISO] "
                    "Aucun executable "
                    "SLES_526.xx detecte."
                )

                return False

            version_iso = version_iso.upper()

            print()
            print(
                "[PS2 ISO] "
                "Version detectee :",
                version_iso
            )

            # =============================================
            # RECHERCHE DATA
            # =============================================

            data_iso = lecteur_iso.trouver(
                "DATA"
            )

            if data_iso is None:

                print()
                print(
                    "[PS2 ISO] "
                    "Dossier DATA introuvable."
                )

                return False

            # =============================================
            # PREPARATION DE PS2_VERSION
            # =============================================

            if PS2_VERSION.exists():

                print()
                print(
                    "[PS2 ISO] "
                    "Nettoyage de l'ancienne "
                    "copie locale..."
                )

                shutil.rmtree(
                    PS2_VERSION
                )

            PS2_VERSION.mkdir(
                parents=True,
                exist_ok=True
            )

            # =============================================
            # COPIE EXECUTABLE PS2
            # =============================================

            executable_iso = (
                lecteur_iso.trouver(
                    version_iso
                )
            )

            if executable_iso is not None:

                lecteur_iso.extraire_fichier(
                    executable_iso,
                    PS2_VERSION / version_iso
                )

            else:

                print()
                print(
                    "[PS2 ISO] "
                    "Executable PS2 introuvable."
                )

                return False

            # =============================================
            # EXTRACTION DES FICHIERS RACINE REQUIS
            # =============================================

            # ps2_contient_donnees() exige, en plus de DATA et du SLES :
            #   - LARRY.INI
            #   - SYSTEM.CNF
            #
            # L'ancienne branche ISO n'extrayait que DATA + SLES, donc la
            # copie était forcément déclarée invalide après l'extraction.
            for nom_racine in ("LARRY.INI", "SYSTEM.CNF"):

                entree_racine = lecteur_iso.trouver(
                    nom_racine
                )

                if entree_racine is None:

                    print()
                    print(
                        "[PS2 ISO] Fichier racine requis introuvable :",
                        nom_racine
                    )

                    return False

                lecteur_iso.extraire_fichier(
                    entree_racine,
                    PS2_VERSION / nom_racine
                )

                print(
                    "[PS2 ISO] Fichier racine extrait :",
                    nom_racine
                )

            # =============================================
            # EXTRACTION DATA
            # =============================================

            destination_data = (
                PS2_VERSION / "DATA"
            )

            print()
            print(
                "[PS2 ISO] "
                "Extraction DATA vers :"
            )

            print(
                destination_data
            )

            lecteur_iso.extraire_dossier(
                data_iso,
                destination_data
            )

            # =============================================
            # VERIFICATION
            # =============================================

            if not ps2_contient_donnees():

                print()
                print(
                    "[PS2 ISO] "
                    "La copie locale obtenue "
                    "n'est pas valide."
                )

                data_locale = trouver_entree_racine_ci(
                    PS2_VERSION,
                    "DATA"
                )

                larry_ini = trouver_entree_racine_ci(
                    PS2_VERSION,
                    "LARRY.INI"
                )

                system_cnf = trouver_entree_racine_ci(
                    PS2_VERSION,
                    "SYSTEM.CNF"
                )

                executable_local = trouver_executable_ps2(
                    PS2_VERSION
                )

                print(
                    "[PS2 ISO] DATA       :",
                    "OK" if data_locale is not None else "ABSENT"
                )

                print(
                    "[PS2 ISO] LARRY.INI  :",
                    "OK" if larry_ini is not None else "ABSENT"
                )

                print(
                    "[PS2 ISO] SYSTEM.CNF :",
                    "OK" if system_cnf is not None else "ABSENT"
                )

                print(
                    "[PS2 ISO] Executable :",
                    (
                        executable_local.name
                        if executable_local is not None
                        else "ABSENT"
                    )
                )

                nombre_jam = 0

                if data_locale is not None and data_locale.is_dir():
                    nombre_jam = sum(
                        1
                        for fichier in data_locale.rglob("*")
                        if (
                            fichier.is_file()
                            and fichier.suffix.lower() == ".jam"
                        )
                    )

                print(
                    "[PS2 ISO] JAM trouves :",
                    nombre_jam
                )

                return False

            executable_local = (
                trouver_executable_ps2(
                    PS2_VERSION
                )
            )

            print()
            print("=" * 70)

            print(
                "JEU PS2 PRET POUR LA CONVERSION"
            )

            print("=" * 70)

            print()

            print(
                "Version :",
                (
                    executable_local.name
                    if executable_local is not None
                    else version_iso
                )
            )

            print(
                "Source  : ISO non montee"
            )

            print(
                "DATA    :",
                destination_data
            )

            return True

    # =====================================================
    # 6. ISO ILLISIBLE / INCOMPATIBLE
    # =====================================================

    except Exception as erreur:

        print()
        print("=" * 70)
        print("ERREUR LECTURE ISO PS2")
        print("=" * 70)

        print()
        print(
            "[PS2 ISO]",
            erreur
        )

        print()
        print(
            "Le programme continue "
            "sans source PS2."
        )

        return False


def dimensions_pillow(bloc):
    """
    Implémente le traitement interne `dimensions_pillow` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        bloc.
    
    Connexions:
        Appelée par : gif_valide, ico_valide, jpg_valide, webp_valide.
        Appelle : aucune autre fonction interne directe détectée.
    """
    try:

        with Image.open(io.BytesIO(bloc)) as image:

            return image.size

    except Exception:

        return None


def bmp_valide(data, pos):
    """
    Implémente le traitement interne `bmp_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : aucune autre fonction interne directe détectée.
    """
    if (pos + 26 > len(data) or data[pos:pos + 2] != b"BM"):
        return None

    try:

        taille = struct.unpack_from("<I", data, pos + 2)[0]

        dib = struct.unpack_from("<I", data, pos + 14)[0]

        if dib == 12:

            w = struct.unpack_from("<H", data, pos + 18)[0]

            h = struct.unpack_from("<H", data, pos + 20)[0]

            bpp = struct.unpack_from("<H", data, pos + 24)[0]

            compression = 0

        else:

            if pos + 54 > len(data):
                return None

            w = abs(struct.unpack_from("<i", data, pos + 18)[0])

            h = abs(struct.unpack_from("<i", data, pos + 22)[0])

            bpp = struct.unpack_from("<H", data, pos + 28)[0]

            compression = struct.unpack_from("<I", data, pos + 30)[0]

    except struct.error:
        return None

    if dib not in (12, 40, 52, 56, 108, 124):
        return None

    if bpp not in (1, 4, 8, 16, 24, 32):
        return None

    if not (1 <= w <= 8192 and 1 <= h <= 8192):
        return None

    if (taille < 26 or pos + taille > len(data)):
        return None

    return {
        "format": "BMP",
        "extension": ".bmp",
        "taille": taille,
        "largeur": w,
        "hauteur": h,
        "bpp": bpp,
        "compression": compression,
        "description": f"{w}x{h}__{bpp}bpp",
    }


def dds_valide(data, pos):
    """
    Implémente le traitement interne `dds_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : aucune autre fonction interne directe détectée.
    """
    if (pos + 128 > len(data) or data[pos:pos + 4] != b"DDS "):
        return None

    try:

        header = struct.unpack_from("<I", data, pos + 4)[0]

        h = struct.unpack_from("<I", data, pos + 12)[0]

        w = struct.unpack_from("<I", data, pos + 16)[0]

        mipmaps = max(1, struct.unpack_from("<I", data, pos + 28)[0])

        pf = struct.unpack_from("<I", data, pos + 76)[0]

        fourcc = data[pos + 84:pos + 88]

    except struct.error:
        return None

    if header != 124 or pf != 32:
        return None

    bloc8 = (
        b"DXT1",
        b"ATI1",
        b"BC4U",
        b"BC4S",
    )

    bloc16 = (
        b"DXT3",
        b"DXT5",
        b"ATI2",
        b"BC5U",
        b"BC5S",
    )

    if fourcc in bloc8:
        bloc = 8

    elif fourcc in bloc16:
        bloc = 16

    else:
        return None

    if not (1 <= w <= 8192 and 1 <= h <= 8192):
        return None

    taille = 128

    mw = w
    mh = h

    for _ in range(mipmaps):

        taille += (max(1, (mw + 3) // 4) * max(1, (mh + 3) // 4) * bloc)

        mw = max(1, mw // 2)

        mh = max(1, mh // 2)

    if pos + taille > len(data):
        return None

    fmt = fourcc.decode("ascii", errors="replace")

    return {
        "format": "DDS",
        "extension": ".dds",
        "taille": taille,
        "largeur": w,
        "hauteur": h,
        "fourcc": fmt,
        "mipmaps": mipmaps,
        "description": f"{w}x{h}__{fmt}",
    }


def jpg_valide(data, pos):
    """
    Implémente le traitement interne `jpg_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : dimensions_pillow.
    """
    if (data[pos:pos + 3] != b"\xFF\xD8\xFF"):
        return None

    fin = data.find(b"\xFF\xD9", pos + 3)

    if fin < 0:
        return None

    taille = (fin + 2 - pos)

    if taille < 100:
        return None

    dim = dimensions_pillow(data[pos:pos + taille])

    if not dim:
        return None

    w, h = dim

    return {
        "format": "JPG",
        "extension": ".jpg",
        "taille": taille,
        "largeur": w,
        "hauteur": h,
        "description": f"{w}x{h}",
    }


def png_valide(data, pos):
    """
    Implémente le traitement interne `png_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : aucune autre fonction interne directe détectée.
    """
    signature = (b"\x89PNG\r\n\x1a\n")

    if (data[pos:pos + 8] != signature):
        return None

    if pos + 24 > len(data):
        return None

    try:

        w, h = struct.unpack_from(">II", data, pos + 16)

    except struct.error:
        return None

    p = pos + 8

    while p + 12 <= len(data):

        longueur = struct.unpack_from(">I", data, p)[0]

        type_chunk = data[p + 4:p + 8]

        p += longueur + 12

        if p > len(data):
            return None

        if type_chunk == b"IEND":

            return {
                "format": "PNG",
                "extension": ".png",
                "taille": p - pos,
                "largeur": w,
                "hauteur": h,
                "description": f"{w}x{h}",
            }

    return None


def webp_valide(data, pos):
    """
    Implémente le traitement interne `webp_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : dimensions_pillow.
    """
    if pos + 12 > len(data):
        return None

    if (data[pos:pos + 4] != b"RIFF" or data[pos + 8:pos + 12] != b"WEBP"):
        return None

    taille = (struct.unpack_from("<I", data, pos + 4)[0] + 8)

    if (taille < 16 or pos + taille > len(data)):
        return None

    dim = dimensions_pillow(data[pos:pos + taille])

    if not dim:
        return None

    return {
        "format": "WEBP",
        "extension": ".webp",
        "taille": taille,
        "largeur": dim[0],
        "hauteur": dim[1],
        "description": f"{dim[0]}x{dim[1]}",
    }


def gif_valide(data, pos):
    """
    Implémente le traitement interne `gif_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : dimensions_pillow.
    """
    if data[pos:pos + 6] not in (b"GIF87a", b"GIF89a"):
        return None

    recherche = pos + 13

    while True:

        fin = data.find(b"\x3B", recherche)

        if fin < 0:
            return None

        taille = (fin + 1 - pos)

        dim = dimensions_pillow(data[pos:pos + taille])

        if dim:

            return {
                "format": "GIF",
                "extension": ".gif",
                "taille": taille,
                "largeur": dim[0],
                "hauteur": dim[1],
                "description": f"{dim[0]}x{dim[1]}",
            }

        recherche = fin + 1


def ico_valide(data, pos):
    """
    Implémente le traitement interne `ico_valide` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data, pos.
    
    Connexions:
        Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
        Appelle : dimensions_pillow.
    """
    if (data[pos:pos + 4] != b"\x00\x00\x01\x00"):
        return None

    if pos + 6 > len(data):
        return None

    nombre = struct.unpack_from("<H", data, pos + 4)[0]

    if not (1 <= nombre <= 256):
        return None

    max_fin = 0

    for index in range(nombre):

        p = (pos + 6 + index * 16)

        if p + 16 > len(data):
            return None

        taille = struct.unpack_from("<I", data, p + 8)[0]

        offset = struct.unpack_from("<I", data, p + 12)[0]

        max_fin = max(max_fin, offset + taille)

    if (max_fin < 22 or pos + max_fin > len(data)):
        return None

    dim = dimensions_pillow(data[pos:pos + max_fin])

    if not dim:
        return None

    return {
        "format": "ICO",
        "extension": ".ico",
        "taille": max_fin,
        "largeur": dim[0],
        "hauteur": dim[1],
        "description": f"{dim[0]}x{dim[1]}",
    }



def image_valide(chemin):
    """
    VALIDATEUR CENTRAL DES IMAGES EXTRAITES.

    Reconnecte tous les validateurs spécialisés du moteur :
        BMP       -> bmp_valide()
        DDS       -> dds_valide()
        JPG/JPEG  -> jpg_valide()
        PNG       -> png_valide()
        WEBP      -> webp_valide()
        GIF       -> gif_valide()
        ICO       -> ico_valide()

    Le fichier réellement écrit sur le disque est relu puis contrôlé.
    Retourne les informations du validateur si l'image est correcte,
    sinon None.
    """
    chemin = Path(chemin)

    if not chemin.is_file():
        return None

    try:
        data = chemin.read_bytes()
    except OSError:
        return None

    if not data:
        return None

    validateurs = {
        ".bmp": bmp_valide,
        ".dds": dds_valide,
        ".jpg": jpg_valide,
        ".jpeg": jpg_valide,
        ".png": png_valide,
        ".webp": webp_valide,
        ".gif": gif_valide,
        ".ico": ico_valide,
    }

    validateur = validateurs.get(chemin.suffix.lower())

    if validateur is None:
        return None

    try:
        information = validateur(data, 0)
    except (OSError, ValueError, TypeError, struct.error):
        return None

    if not information:
        return None

    # L'extraction doit correspondre exactement à l'image détectée.
    # Cela détecte aussi les fichiers tronqués ou suivis de données parasites.
    if information.get("taille") != len(data):
        return None

    return information


DETECTEURS = (
    (b"BM", bmp_valide),
    (b"DDS ", dds_valide),
    (b"\xFF\xD8\xFF", jpg_valide),
    (b"\x89PNG\r\n\x1a\n", png_valide),
    (b"GIF87a", gif_valide),
    (b"GIF89a", gif_valide),
    (b"RIFF", webp_valide),
    (b"\x00\x00\x01\x00", ico_valide),
)

DETECTEURS_PAR_SIGNATURE = {
    signature: detecteur
    for signature, detecteur in DETECTEURS
}

SIGNATURES_IMAGES_RE = re.compile(b"|".join(
    re.escape(signature) for signature, _ in DETECTEURS))

SIGNATURES_INCONNUES = {
    b"8BPS": "PSD",
    b"TIM2": "TIM2",
    b"II*\x00": "TIFF_LE",
    b"MM\x00*": "TIFF_BE",
}

SIGNATURES_INCONNUES_RE = re.compile(b"|".join(
    re.escape(signature) for signature in SIGNATURES_INCONNUES))


def scanner_images_jam_mmap(jam, jam_root):
    """
    Implémente le traitement interne `scanner_images_jam_mmap` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        jam, jam_root.
    
    Connexions:
        Appelée par : extraire_images.
        Appelle : aucune autre fonction interne directe détectée.
    """

    candidats = []
    inconnus = []

    if jam.stat().st_size == 0:
        return candidats, inconnus

    with jam.open("rb") as flux:

        with mmap.mmap(flux.fileno(), 0, access=mmap.ACCESS_READ) as data:

            for correspondance in SIGNATURES_IMAGES_RE.finditer(data):

                signature = correspondance.group(0)
                position = correspondance.start()
                detecteur = DETECTEURS_PAR_SIGNATURE[signature]
                information = detecteur(data, position)

                if information:
                    candidats.append((position, information))

            for correspondance in SIGNATURES_INCONNUES_RE.finditer(data):

                signature = correspondance.group(0)
                position = correspondance.start()

                inconnus.append({
                    "jam": str(jam.relative_to(jam_root)),
                    "type": SIGNATURES_INCONNUES[signature],
                    "offset": position,
                    "offset_hex": f"0x{position:08X}",
                })

    return candidats, inconnus


def dossier_extraction_images_ps2():
    """
    Retourne le dossier d'extraction propre à l'édition PS2 locale.

    Exemple :
        SLES_526.42
        -> EDITION_IMAGE/All_Image_extract/PS2_EN_SLES_526.42
    """
    executable = trouver_executable_ps2(PS2_VERSION)

    if executable is None:
        return None

    version = executable.name.upper()

    # Nom demandé pour séparer totalement les éditions.

    return IMAGE_EXTRACT / f"IMG_PS2_EN_{version}"


def extraction_images_ps2_complete(dossier):
    """Vérifie qu'une extraction PS2 a été terminée proprement."""
    if dossier is None:
        return False

    marqueur = Path(dossier) / "extraction_complete.txt"

    return (
        Path(dossier).is_dir()
        and marqueur.is_file()
    )


def index_noms_jam_pc_pour_images():
    """Index PC utilisé uniquement pour la casse des noms d'images PS2."""
    jam_root_pc = PC_VERSION_BACKUP / "Data" / "JamFiles" / "PC"

    if not jam_root_pc.exists():
        jam_root_pc = PC_VERSION / "Data" / "JamFiles" / "PC"

    index = {}

    if not jam_root_pc.exists():
        return index

    for jam_pc in jam_root_pc.rglob("*"):
        if not jam_pc.is_file() or jam_pc.suffix.lower() != ".jam":
            continue

        relatif = str(
            jam_pc.relative_to(jam_root_pc)
        ).replace("\\", "__").replace("/", "__")

        index[relatif.casefold()] = relatif

    return index


def nom_image_ps2_normalise(jam, jam_root, index_jam_pc):
    """
    Normalise UNIQUEMENT le préfixe du nom des images extraites PS2.

    Exemple :
        PS2__LOADSCRN.JAM__BMP__0019__004881D4__512x512__8bpp.bmp
        ->
        LoadScrn.JAM__BMP__0019__004881D4__512x512__8bpp.bmp

    Aucun fichier JAM source n'est renommé.
    """
    relatif_ps2 = nom_jam(jam, jam_root)

    # L'ancien extracteur pouvait préfixer le nom logique par PS2__.
    # Ce préfixe ne doit jamais apparaître dans le nom final de l'image.
    while relatif_ps2.upper().startswith("PS2__"):
        relatif_ps2 = relatif_ps2[5:]

    # Reprend automatiquement la casse exacte utilisée par le JAM PC.
    # Ex. LOADSCRN.JAM -> LoadScrn.JAM
    return index_jam_pc.get(
        relatif_ps2.casefold(),
        relatif_ps2
    )


def extraire_images_ps2_version():
    """
    Extrait les BMP, DDS et ICO de la copie PS2_VERSION courante
    dans un dossier séparé selon le SLES détecté.

    Une extraction déjà validée pour la même édition est conservée.
    Une extraction incomplète est reconstruite.
    """
    executable = trouver_executable_ps2(PS2_VERSION)

    if executable is None:
        print("[IMAGES PS2] Version PS2 introuvable.")
        return False

    version = executable.name.upper()

    destination_root = IMAGE_EXTRACT / f"IMG_PS2_EN_{version}"

    marqueur = destination_root / "extraction_complete.txt"

    if extraction_images_ps2_complete(destination_root):
        print(
            "[IMAGES PS2] Extraction deja complete :",
            destination_root.name
        )
        return True

    jam_root = PS2_VERSION / "Data" / "JamFiles"

    if not jam_root.exists():
        print("[IMAGES PS2] Data/JamFiles absent.")
        return False

    # Si une ancienne extraction a été interrompue, on ne la mélange
    # pas avec la nouvelle.
    if destination_root.exists():
        print(
            "[IMAGES PS2] Extraction incomplete detectee, reconstruction :",
            destination_root.name
        )
        supprimer(destination_root)

    destination_root.mkdir(parents=True, exist_ok=True)

    # Seulement les formats demandés pour la bibliothèque PS2.
    for format_image in ("BMP", "DDS", "ICO"):
        (destination_root / format_image).mkdir(
            parents=True,
            exist_ok=True
        )

    manifeste = {}
    inconnus = []
    total = {
        "BMP": 0,
        "DDS": 0,
        "ICO": 0,
    }

    jams = [
        p for p in jam_root.rglob("*")
        if p.is_file() and p.suffix.lower() == ".jam"
    ]

    print()
    print("=" * 70)
    print("EXTRACTION IMAGES PS2 :", version)
    print("=" * 70)
    print("JAM analyses :", len(jams))
    print("Destination :", destination_root)

    debut_extraction = time.perf_counter()

    # Utilisé uniquement pour donner aux images PS2 le même
    # nom/casse que les images PC correspondantes.
    index_jam_pc = index_noms_jam_pc_pour_images()

    for jam in sorted(jams):
        candidats, inconnus_jam = scanner_images_jam_mmap(
            jam,
            jam_root
        )
        inconnus.extend(inconnus_jam)

        candidats.sort(
            key=lambda item: (
                item[0],
                -item[1]["taille"]
            )
        )

        retenus = []

        for pos, info in candidats:
            fin = pos + info["taille"]

            imbrique = any(
                pos >= ancien_pos
                and fin <= (
                    ancien_pos
                    + ancien_info["taille"]
                )
                for ancien_pos, ancien_info in retenus
            )

            if not imbrique:
                retenus.append((pos, info))

        compte = {}

        with jam.open("rb") as flux_images:

            for pos, info in retenus:
                fmt = info["format"].upper()

                # Bibliothèque PS2 demandée : BMP / DDS / ICO.
                if fmt not in ("BMP", "DDS", "ICO"):
                    continue

                compte[fmt] = compte.get(fmt, 0) + 1
                total[fmt] += 1

                numero = compte[fmt]

                nom_jam_image = nom_image_ps2_normalise(
                    jam,
                    jam_root,
                    index_jam_pc
                )

                nom = (
                    f"{nom_jam_image}"
                    f"__{fmt}"
                    f"__{numero:04d}"
                    f"__{pos:08X}"
                    f"__{info['description']}"
                    f"{info['extension']}"
                )

                # Sécurité finale : aucune image extraite PS2 ne conserve
                # le préfixe historique "PS2__".
                while nom.upper().startswith("PS2__"):
                    nom = nom[5:]

                flux_images.seek(pos)
                bloc_image = flux_images.read(
                    info["taille"]
                )

                if len(bloc_image) != info["taille"]:
                    raise RuntimeError(
                        "Lecture image PS2 incomplete : "
                        f"{jam} a 0x{pos:X}"
                    )

                destination = chemin_image_classee(
                    destination_root,
                    fmt,
                    info["largeur"],
                    info["hauteur"],
                    nom,
                )

                destination.parent.mkdir(
                    parents=True,
                    exist_ok=True
                )

                destination.write_bytes(
                    bloc_image
                )


                # Validation finale du fichier PS2 réellement écrit.
                validation_image = image_valide(destination)

                if validation_image is None:
                    destination.unlink(missing_ok=True)
                    raise RuntimeError(
                        "Image PS2 extraite invalide : "
                        f"{destination}"
                    )

                entree = {
                    "jam": str(
                        jam.relative_to(jam_root)
                    ),
                    "format": fmt,
                    "extension": info["extension"],
                    "offset": pos,
                    "offset_hex": f"0x{pos:08X}",
                    "taille": info["taille"],
                    "poids_octets": info["taille"],
                    "largeur": info["largeur"],
                    "hauteur": info["hauteur"],
                    "sha256": sha256(bloc_image),
                    "edition_ps2": version,
                }

                for champ in (
                    "bpp",
                    "compression",
                    "fourcc",
                    "mipmaps",
                ):
                    if champ in info:
                        entree[champ] = info[champ]

                manifeste[nom] = entree

    # Manifestes propres à cette édition : ils ne remplacent pas
    # le manifeste PC utilisé par l'injection actuelle.
    (destination_root / "emplacement_image.json").write_text(
        json.dumps(
            manifeste,
            indent=4,
            ensure_ascii=False
        ),
        encoding="utf-8"
    )

    (destination_root / "signatures_images_non_prises_en_charge.json").write_text(
        json.dumps(
            inconnus,
            indent=4,
            ensure_ascii=False
        ),
        encoding="utf-8"
    )

    # Le marqueur n'est écrit qu'à la toute fin : sa présence signifie
    # donc que l'extraction a réellement été terminée.
    marqueur.write_text(
        "EXTRACTION IMAGES PS2 COMPLETE\n"
        f"Edition PS2 : {version}\n"
        f"BMP : {total['BMP']}\n"
        f"DDS : {total['DDS']}\n"
        f"ICO : {total['ICO']}\n",
        encoding="utf-8"
    )

    print()
    print("[IMAGES PS2] Extraction terminee :", version)

    for fmt in ("BMP", "DDS", "ICO"):
        print(f"{fmt:6} :", total[fmt])

    print(
        "[IMAGES PS2] Temps total :",
        f"{time.perf_counter() - debut_extraction:.3f} s"
    )

    return True


def extraire_images():
    # Bibliothèque des images extraites exclusivement depuis
    # la version PC de référence.
    image_extract_pc = IMAGE_EXTRACT / "IMG_PC_VERSION_BACKUP"
    image_extract_pc.mkdir(parents=True, exist_ok=True)
    """
    Extrait images.
    
    Connexions:
        Appelée par : construire_version_fr, initialiser, injecter_images, injecter_langue_ps2, main, menu.
        Appelle : nom_jam, scanner_images_jam_mmap, sha256, supprimer, titre.
    """
    titre("EXTRACTION DE TOUTES LES IMAGES")

    data_root = PC_VERSION / "Data"
    jam_root = data_root / "JamFiles" / "PC"

    if not jam_root.exists():
        raise RuntimeError("PC_VERSION/Data/JamFiles/PC absent.")

    supprimer(image_extract_pc)
    image_extract_pc.mkdir(parents=True, exist_ok=True)

    creer_dossiers_images(image_extract_pc)

    manifeste = {}
    inconnus = []
    total = {}

    jams = [
        p for p in jam_root.rglob("*")
        if p.is_file() and p.suffix.lower() == ".jam"
    ]
    print("JAM analyses :", len(jams))
    debut_extraction = time.perf_counter()

    for jam in sorted(jams):
        debut_jam = time.perf_counter()
        candidats, inconnus_jam = scanner_images_jam_mmap(jam, jam_root)
        inconnus.extend(inconnus_jam)

        # --- CORRECTION DU TRI SÉCURISÉ ---
        # On trie d'abord par offset (croissant), puis par taille (décroissante) via l'indice de l'info [1]
        candidats.sort(key=lambda item: (item[0], -item[1]["taille"]))
        # ----------------------------------

        retenus = []
        for pos, info in candidats:
            fin = pos + info["taille"]
            imbrique = any(pos >= p and fin <= (p + i["taille"])
                           for p, i in retenus)
            if not imbrique:
                retenus.append((pos, info))

        compte = {}
        flux_images = jam.open("rb")

        for pos, info in retenus:
            fmt = info["format"]
            compte[fmt] = compte.get(fmt, 0) + 1
            total[fmt] = total.get(fmt, 0) + 1
            numero = compte[fmt]

            nom = (f"{nom_jam(jam, jam_root)}"
                   f"__{fmt}"
                   f"__{numero:04d}"
                   f"__{pos:08X}"
                   f"__{info['description']}"
                   f"{info['extension']}")

            flux_images.seek(pos)
            bloc = flux_images.read(info["taille"])

            if len(bloc) != info["taille"]:
                flux_images.close()
                raise RuntimeError(f"Lecture incomplète : {jam} à 0x{pos:X}")

            destination = chemin_image_classee(
                image_extract_pc,
                fmt,
                info["largeur"],
                info["hauteur"],
                nom,
            )
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(bloc)

            # Validation finale du fichier PC réellement écrit.
            validation_image = image_valide(destination)

            if validation_image is None:
                destination.unlink(missing_ok=True)
                flux_images.close()
                raise RuntimeError(
                    "Image PC extraite invalide : "
                    f"{destination}"
                )


            entree = {
                "jam": str(jam.relative_to(jam_root)),
                "format": fmt,
                "extension": info["extension"],
                "offset": pos,
                "offset_hex": f"0x{pos:08X}",
                "taille": info["taille"],
                "poids_octets": info["taille"],
                "largeur": info["largeur"],
                "hauteur": info["hauteur"],
                "sha256": sha256(bloc),
            }

            for champ in ("bpp", "compression", "fourcc", "mipmaps"):
                if champ in info:
                    entree[champ] = info[champ]

            manifeste[nom] = entree

        flux_images.close()
        duree_jam = time.perf_counter() - debut_jam

        print("[SCAN IMAGE]", jam.relative_to(jam_root),
              f": {duree_jam:.3f} s,", len(retenus), "image(s)")

    MANIFEST.write_text(json.dumps(manifeste, indent=4, ensure_ascii=False),
                        encoding="utf-8")
    UNKNOWN_IMAGES.write_text(json.dumps(inconnus,
                                         indent=4,
                                         ensure_ascii=False),
                              encoding="utf-8")

    print()
    print("Extraction validee :")
    for fmt in sorted(total):
        print(f"{fmt:6} :", total[fmt])

    print()
    print("Manifest :", MANIFEST)
    print("[SCAN OPTIMISE] Temps total :",
          f"{time.perf_counter() - debut_extraction:.3f} s")


def nom_jam(jam, jam_root):
    """
    Détermine le nom jam.
    
    Paramètres:
        jam, jam_root.
    
    Connexions:
        Appelée par : extraire_images.
        Appelle : aucune autre fonction interne directe détectée.
    """
    return str(jam.relative_to(jam_root)).replace("\\",
                                                  "__").replace("/", "__")


def normaliser_bmp_image(image, original):
    """
    Normalise bmp image.
    
    Paramètres:
        image, original.
    
    Connexions:
        Appelée par : normaliser_bmp.
        Appelle : aucune autre fonction interne directe détectée.
    """
    template = bytearray(original)

    if template[:2] != b"BM":

        raise ValueError("BMP original invalide")

    dib = struct.unpack_from("<I", template, 14)[0]

    if dib < 40:

        raise ValueError("BMP ancien : fournir un BMP "
                         "de taille binaire identique")

    offset = struct.unpack_from("<I", template, 10)[0]

    largeur = abs(struct.unpack_from("<i", template, 18)[0])

    hauteur_brute = (struct.unpack_from("<i", template, 22)[0])

    hauteur = abs(hauteur_brute)

    bpp = struct.unpack_from("<H", template, 28)[0]

    compression = struct.unpack_from("<I", template, 30)[0]

    if compression != 0:

        raise ValueError(f"BMP compresse {compression}")

    if image.size != (largeur, hauteur):

        raise ValueError(f"dimensions {image.size} != "
                         f"{largeur}x{hauteur}")

    stride = ((largeur * bpp + 31) // 32) * 4

    zone = (stride * hauteur)

    if (offset + zone > len(template)):

        raise ValueError("Zone pixels BMP invalide")

    bas_haut = (hauteur_brute > 0)

    pixels_sortie = bytearray(zone)

    if bpp == 24:

        img = image.convert("RGB")

        px = img.load()

        for ligne in range(hauteur):

            y = (hauteur - 1 - ligne if bas_haut else ligne)

            dest = (ligne * stride)

            for x in range(largeur):

                r, g, b = px[x, y]

                p = (dest + x * 3)

                pixels_sortie[p:p + 3] = bytes((b, g, r))

    elif bpp == 32:

        img = image.convert("RGBA")

        px = img.load()

        for ligne in range(hauteur):

            y = (hauteur - 1 - ligne if bas_haut else ligne)

            dest = (ligne * stride)

            for x in range(largeur):

                r, g, b, a = (px[x, y])

                p = (dest + x * 4)

                pixels_sortie[p:p + 4] = bytes((b, g, r, a))

    elif bpp == 8:

        palette_debut = (14 + dib)

        palette_octets = (offset - palette_debut)

        couleurs = min(256, palette_octets // 4)

        if couleurs < 2:

            raise ValueError("Palette BMP invalide")

        q = image.convert("RGB").quantize(colors=couleurs,
                                          method=(Image.Quantize.MEDIANCUT),
                                          dither=(Image.Dither.FLOYDSTEINBERG))

        palette = q.getpalette()

        for index in range(couleurs):

            r = palette[index * 3]

            g = palette[index * 3 + 1]

            b = palette[index * 3 + 2]

            p = (palette_debut + index * 4)

            template[p:p + 4] = bytes((b, g, r, 0))

        brut = q.tobytes()

        for ligne in range(hauteur):

            y = (hauteur - 1 - ligne if bas_haut else ligne)

            src = (y * largeur)

            dst = (ligne * stride)

            pixels_sortie[dst:dst + largeur] = brut[src:src + largeur]

    else:

        raise ValueError(f"BMP {bpp}bpp : "
                         "conversion automatique non geree")

    template[offset:offset + zone] = pixels_sortie

    return bytes(template)


def normaliser_bmp(fichier, original):
    """
    Normalise bmp.
    
    Paramètres:
        fichier, original.
    
    Connexions:
        Appelée par : injecter_ecran_sierra_localise, injecter_images.
        Appelle : normaliser_bmp_image.
    """
    if (fichier.suffix.lower() == ".bmp"):

        brut = fichier.read_bytes()

        if len(brut) == len(original):

            try:

                img = Image.open(io.BytesIO(brut))

                if img.size == Image.open(io.BytesIO(original)).size:

                    return brut

            except Exception:
                pass

    with Image.open(fichier) as image:

        return normaliser_bmp_image(image, original)


def rgb565(r, g, b):
    """
    Convertit une couleur vers RGB565.
    
    Paramètres:
        r, g, b.
    
    Connexions:
        Appelée par : bloc_couleur.
        Appelle : aucune autre fonction interne directe détectée.
    """
    return (((r * 31 + 127) // 255) << 11
            | ((g * 63 + 127) // 255) << 5
            | ((b * 31 + 127) // 255))


def rgb565_inverse(c):
    """
    Convertit une couleur vers RGB565 inverse.
    
    Paramètres:
        c.
    
    Connexions:
        Appelée par : palette_couleur.
        Appelle : aucune autre fonction interne directe détectée.
    """
    return (
        ((c >> 11) & 31) * 255 // 31,
        ((c >> 5) & 63) * 255 // 63,
        (c & 31) * 255 // 31,
    )


def palette_couleur(c0, c1, transparent):
    """
    Implémente le traitement interne `palette_couleur` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        c0, c1, transparent.
    
    Connexions:
        Appelée par : bloc_couleur.
        Appelle : rgb565_inverse.
    """
    a = rgb565_inverse(c0)

    b = rgb565_inverse(c1)

    if transparent:

        c2 = tuple((a[i] + b[i]) // 2 for i in range(3))

        return [
            a,
            b,
            c2,
            (0, 0, 0),
        ]

    c2 = tuple((2 * a[i] + b[i]) // 3 for i in range(3))

    c3 = tuple((a[i] + 2 * b[i]) // 3 for i in range(3))

    return [
        a,
        b,
        c2,
        c3,
    ]


def bloc_couleur(pixels, autoriser_transparence):
    """
    Implémente le traitement interne `bloc_couleur` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        pixels, autoriser_transparence.
    
    Connexions:
        Appelée par : encoder_dxt.
        Appelle : palette_couleur, rgb565.
    """
    transparent = (autoriser_transparence
                   and any(a < 128 for _, _, _, a in pixels))

    couleurs = [(r, g, b) for r, g, b, a in pixels
                if (not transparent or a >= 128)]

    if not couleurs:
        couleurs = [(0, 0, 0)]

    sombre = min(couleurs, key=lambda c: sum(c))

    clair = max(couleurs, key=lambda c: sum(c))

    c0 = rgb565(*clair)

    c1 = rgb565(*sombre)

    if transparent:

        if c0 > c1:
            c0, c1 = c1, c0

    else:

        if c0 < c1:
            c0, c1 = c1, c0

        elif c0 == c1:
            if c0 < 65535:
                c0 += 1
            else:
                c1 -= 1

        if c0 <= c1:
            raise RuntimeError(
                "Bloc DXT opaque invalide : c0 doit être supérieur à c1.")

    palette = palette_couleur(c0, c1, transparent)

    bits = 0

    for index, pixel in enumerate(pixels):

        r, g, b, a = pixel

        if (transparent and a < 128):
            choix = 3

        else:

            limite = (3 if transparent else 4)

            choix = min(range(limite),
                        key=lambda i: (r - palette[i][0])**2 +
                        (g - palette[i][1])**2 + (b - palette[i][2])**2)

        bits |= (choix << (index * 2))

    return struct.pack("<HHI", c0, c1, bits)


def pixels_bloc(image, bx, by):
    """
    Implémente le traitement interne `pixels_bloc` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        image, bx, by.
    
    Connexions:
        Appelée par : encoder_dxt.
        Appelle : aucune autre fonction interne directe détectée.
    """
    px = image.load()

    return [
        px[min(bx + x, image.width - 1),
           min(by + y, image.height - 1)] for y in range(4) for x in range(4)
    ]


def encoder_dxt(image, fourcc):
    """
    Encode dxt.
    
    Paramètres:
        image, fourcc.
    
    Connexions:
        Appelée par : reconstruire_dds.
        Appelle : alpha_dxt3, alpha_dxt5, bloc_couleur, pixels_bloc.
    """
    sortie = bytearray()

    for y in range(0, image.height, 4):

        for x in range(0, image.width, 4):

            pixels = pixels_bloc(image, x, y)

            if fourcc == b"DXT1":

                sortie += bloc_couleur(pixels, True)

            elif fourcc == b"DXT3":

                sortie += alpha_dxt3(pixels)

                sortie += bloc_couleur(pixels, False)

            elif fourcc == b"DXT5":

                sortie += alpha_dxt5(pixels)

                sortie += bloc_couleur(pixels, False)

            else:

                raise ValueError(f"DDS {fourcc!r} "
                                 "non convertible automatiquement")

    return bytes(sortie)


def infos_dds(data):
    """
    Implémente le traitement interne `infos_dds` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data.
    
    Connexions:
        Appelée par : reconstruire_dds.
        Appelle : aucune autre fonction interne directe détectée.
    """
    if (len(data) < 128 or data[:4] != b"DDS "):

        raise ValueError("DDS invalide")

    return {
        "largeur": struct.unpack_from("<I", data, 16)[0],
        "hauteur": struct.unpack_from("<I", data, 12)[0],
        "mipmaps": max(1,
                       struct.unpack_from("<I", data, 28)[0]),
        "fourcc": data[84:88],
    }


def reconstruire_dds(fichier, original):
    """
    Implémente le traitement interne `reconstruire_dds` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        fichier, original.
    
    Connexions:
        Appelée par : injecter_images.
        Appelle : encoder_dxt, infos_dds.
    """
    infos = infos_dds(original)

    if (fichier.suffix.lower() == ".dds"):

        nouveau = (fichier.read_bytes())

        try:

            ni = infos_dds(nouveau)

            if (ni == infos and len(nouveau) == len(original)):

                return nouveau

        except Exception:
            pass

    fourcc = infos["fourcc"]

    if fourcc not in (
            b"DXT1",
            b"DXT3",
            b"DXT5",
    ):

        raise ValueError(f"{fourcc!r} : "
                         "fournir un DDS deja encode")

    image = Image.open(fichier).convert("RGBA")

    dimensions = (infos["largeur"], infos["hauteur"])

    if image.size != dimensions:

        raise ValueError(f"dimensions {image.size} "
                         f"!= {dimensions}")

    corps = bytearray()
    mip = image

    for niveau in range(infos["mipmaps"]):

        corps += encoder_dxt(mip, fourcc)

        if (niveau + 1 < infos["mipmaps"]):

            mip = mip.resize((max(1, mip.width // 2), max(1, mip.height // 2)),
                             Image.Resampling.LANCZOS)

    resultat = (original[:128] + corps)

    if (len(resultat) != len(original)):

        raise ValueError(f"taille DDS generee "
                         f"{len(resultat)} != "
                         f"{len(original)}")

    return resultat


def remplir_slot(payload, taille):
    """
    Remplit slot.
    
    Paramètres:
        payload, taille.
    
    Connexions:
        Appelée par : encoder_generique.
        Appelle : aucune autre fonction interne directe détectée.
    """
    if len(payload) > taille:

        raise ValueError(f"{len(payload)} octets "
                         f"> slot {taille}")

    return (payload + b"\x00" * (taille - len(payload)))


def encoder_generique(fichier, entree):
    """
    Encode generique.
    
    Paramètres:
        fichier, entree.
    
    Connexions:
        Appelée par : injecter_images.
        Appelle : remplir_slot.
    """
    image = Image.open(fichier)

    dimensions = (entree["largeur"], entree["hauteur"])

    if image.size != dimensions:

        raise ValueError(f"dimensions {image.size} "
                         f"!= {dimensions}")

    fmt = entree["format"]

    limite = entree["taille"]

    essais = []

    if fmt == "JPG":

        image = image.convert("RGB")

        for qualite in range(98, 14, -4):

            buffer = io.BytesIO()

            image.save(buffer,
                       format="JPEG",
                       quality=qualite,
                       optimize=True,
                       progressive=False)

            essais.append(buffer.getvalue())

    elif fmt == "PNG":

        for couleurs in (
                None,
                256,
                128,
                64,
        ):

            img = image

            if couleurs:

                img = (image.convert("RGBA").quantize(
                    colors=couleurs, method=(Image.Quantize.FASTOCTREE)))

            buffer = io.BytesIO()

            img.save(buffer, format="PNG", optimize=True, compress_level=9)

            essais.append(buffer.getvalue())

    elif fmt == "GIF":

        buffer = io.BytesIO()

        image.convert("P",
                      palette=(Image.Palette.ADAPTIVE)).save(buffer,
                                                             format="GIF",
                                                             optimize=True)

        essais.append(buffer.getvalue())

    elif fmt == "WEBP":

        for qualite in range(98, 14, -4):

            buffer = io.BytesIO()

            image.save(buffer, format="WEBP", quality=qualite, method=6)

            essais.append(buffer.getvalue())

    elif fmt == "ICO":

        buffer = io.BytesIO()

        image.save(buffer, format="ICO")

        essais.append(buffer.getvalue())

    else:

        raise ValueError(f"Format {fmt} non gere")

    possibles = [payload for payload in essais if len(payload) <= limite]

    if not possibles:

        raise ValueError("Impossible de faire tenir "
                         "l'image dans son emplacement")

    meilleur = max(possibles, key=len)

    return remplir_slot(meilleur, limite)


EXT_IMAGES = {
    ".bmp",
    ".dds",
    ".jpg",
    ".jpeg",
    ".png",
    ".gif",
    ".webp",
    ".ico",
}


def cle_image(nom):
    """
    Implémente le traitement interne `cle_image` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        nom.
    
    Connexions:
        Appelée par : injecter_images.
        Appelle : aucune autre fonction interne directe détectée.
    """
    nom = Path(nom).name

    while (Path(nom).suffix.lower() in EXT_IMAGES):

        nom = Path(nom).stem

    return nom.lower()


def appliquer_padding_espaces_jam(resultat, taille_attendue):
    """
    Applique padding espaces JAM.
    
    Paramètres:
        resultat, taille_attendue.
    
    Connexions:
        Appelée par : construire_payload_compact_fixe, corriger_payload, finaliser_textes_pc_specifiques, patch_textes_menus_fr.
        Appelle : aucune autre fonction interne directe détectée.
    """
    taille_actuelle = len(resultat)
    if taille_actuelle == taille_attendue:
        return resultat
    if taille_actuelle > taille_attendue:
        return None  # Le bloc dépasse la capacité du slot d'origine

    fermeture = resultat.rfind(b"}")
    if fermeture < 0:
        raise RuntimeError(
            "Structure de bloc texte JAM invalide : accolade '}' manquante.")
    reserve = taille_attendue - taille_actuelle
    return resultat[:fermeture] + b" " * reserve + resultat[fermeture:]


def injecter_images(data_root):
    """
    Injecte images.
    
    Paramètres:
        data_root.
    
    Connexions:
        Appelée par : construire_version_fr, injecter_images_depuis_menu, injecter_langue_ps2.
        Appelle : cle_image, encoder_generique, extraire_images, normaliser_bmp, reconstruire_dds, titre.
    """
    titre("INJECTION DES IMAGES MODIFIEES")

    if not MANIFEST.exists():

        print("Manifest absent : extraction automatique.")

        extraire_images()

    manifeste = json.loads(MANIFEST.read_text(encoding="utf-8"))

    index = {}

    for nom, entree in (manifeste.items()):

        index[cle_image(nom)] = (nom, entree)

    fichiers = [
        fichier for fichier in IMAGE_INJECT.rglob("*") if fichier.is_file()
    ]

    if not fichiers:

        print("Aucune image a injecter.")

        return 0

    jam_root = (data_root / "JamFiles" / "PC")

    succes = 0

    for fichier in fichiers:

        trouve = index.get(cle_image(fichier.name))

        if not trouve:

            print("[ABSENT]", fichier.name)

            continue

        nom_original, entree = (trouve)

        jam = (jam_root / Path(entree["jam"]))

        if not jam.exists():

            print("[ABSENT JAM]", jam)

            continue

        original_extrait = chemin_image_classee(
            IMAGE_EXTRACT / "IMG_PC_VERSION_BACKUP",
            entree["format"],
            entree["largeur"],
            entree["hauteur"],
            nom_original,
        )

        if original_extrait.exists():

            original = (original_extrait.read_bytes())

        else:

            data = jam.read_bytes()

            original = data[entree["offset"]:entree["offset"] +
                            entree["taille"]]

        try:

            fmt = entree["format"]

            if fmt == "DDS":

                nouveau = (reconstruire_dds(fichier, original))

            elif fmt == "BMP":

                nouveau = normaliser_bmp(fichier, original)

            else:

                nouveau = (encoder_generique(fichier, entree))

            if (len(nouveau) != entree["taille"]):

                raise ValueError("taille finale incorrecte")

            with jam.open("r+b") as sortie:

                sortie.seek(entree["offset"])

                sortie.write(nouveau)

            print("[OK IMAGE]", fichier.name, "->", entree["jam"])

            succes += 1

        except Exception as erreur:

            print("[REFUS IMAGE]", fichier.name, ":", erreur)

    print("Images injectees :", succes)

    return succes


SIG_JAM = struct.pack("<6I", 0xFF, 0x2D, 0x42, 0x53, 0x8B, 0xA2)

ENTRY = re.compile(
    rb'^([ \t]*)'
    rb'"([^"]+)"'
    rb'([ \t]+)'
    rb'"((?:\\.|[^"\\])*)"'
    rb'([ \t]*)\r?$', re.M)

GLYPH = {
    0xBD: 0xC0,
    0xBE: 0xC1,
    0xC6: 0xC2,
    0xBC: 0xBF,
    0xC7: 0xC3,
    0xFE: 0xB0,
    0xFD: 0xC4,
}

# Les AIS PC n'acceptent pas tous les octets accentues des banques PS2_VERSION.
# L'ancienne table ne couvrait que le francais : les lettres espagnoles et
# la ponctuation inversee pouvaient produire "Data.AIS: invalid string".
# Les codes de GLYPH restent prioritaires dans adapter_fr(), donc les icones
# de commandes du jeu ne sont pas modifies.
ACCENT = {
    0xC0: b"A",
    0xC1: b"A",
    0xC2: b"A",
    0xC3: b"A",
    0xC4: b"A",
    0xC5: b"A",
    0xE0: b"a",
    0xE1: b"a",
    0xE2: b"a",
    0xE3: b"a",
    0xE4: b"a",
    0xE5: b"a",
    0xC7: b"C",
    0xE7: b"c",
    0xC8: b"E",
    0xC9: b"E",
    0xCA: b"E",
    0xCB: b"E",
    0xE8: b"e",
    0xE9: b"e",
    0xEA: b"e",
    0xEB: b"e",
    0xCC: b"I",
    0xCD: b"I",
    0xCE: b"I",
    0xCF: b"I",
    0xEC: b"i",
    0xED: b"i",
    0xEE: b"i",
    0xEF: b"i",
    0xD1: b"N",
    0xF1: b"n",
    0xD2: b"O",
    0xD3: b"O",
    0xD4: b"O",
    0xD5: b"O",
    0xD6: b"O",
    0xF2: b"o",
    0xF3: b"o",
    0xF4: b"o",
    0xF5: b"o",
    0xF6: b"o",
    0xD9: b"U",
    0xDA: b"U",
    0xDB: b"U",
    0xDC: b"U",
    0xF9: b"u",
    0xFA: b"u",
    0xFB: b"u",
    0xFC: b"u",
    0xDD: b"Y",
    0xFF: b"y",
    0xDF: b"ss",
    0x85: b"...",
    0x91: b"'",
    0x92: b"'",
    0x93: b"'",
    0x94: b"'",
    0xA1: b"",
    0xBF: b"",
}

PC_KEYS = {
    "DYNSTR01",
    "DIALBUFF",
    "LOADLOC",
    "LOADSPCE",
    "CTRecBuf",
}

# Le lecteur AIS du jeu réserve 256 octets, terminateur nul compris.
MAX_TEXTE_AIS = 255


def jam_chunks(data):
    """
    Implémente le traitement interne `jam_chunks` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data.
    
    Connexions:
        Appelée par : analyser_jam_detaille, blocs_texte, finaliser_textes_pc_specifiques, remplacer_chunk_variable, traduire_autres_jam, traduire_jam_sans_deplacement, verifier_structure_jam.
        Appelle : aucune autre fonction interne directe détectée.
    """
    resultat = []
    pos = 0

    while True:

        signature = data.find(SIG_JAM, pos)

        if signature < 0:
            break

        header = (signature - 8)

        if header < 0:
            break

        taille1, taille2 = (struct.unpack_from("<II", data, header))

        debut = (header + 32)

        fin = (debut + taille1)

        if fin > len(data):

            pos = signature + 1
            continue

        resultat.append((
            header,
            taille1,
            taille2,
            debut,
            fin,
        ))

        pos = signature + 1

    return resultat


def blocs_texte(data):
    """
    Implémente le traitement interne `blocs_texte` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        data.
    
    Connexions:
        Appelée par : construire_memoire_jam_globale, detecter_langues_ps2, diagnostiquer_localisation_ps2, extraire_entrees_textes_jam, finaliser_textes_pc_specifiques, patch_textes_menus_fr, traduire_autres_jam, traduire_jam_sans_deplacement, traduire_tous_jam_localises.
        Appelle : jam_chunks.
    """
    resultat = []

    for index, (
            header,
            taille1,
            taille2,
            debut,
            fin,
    ) in enumerate(jam_chunks(data)):

        payload = data[debut:fin]

        namespace = re.search(rb'Namespace "([^"]+)"', payload[:500])

        count = re.search(rb'ASCIIString\s*'
                          rb'\[\s*(\d+)\s*\]', payload[:1000])

        if not (namespace and count):
            continue

        resultat.append({
            "chunk_index": index,
            "header": header,
            "size": taille1,
            "begin": debut,
            "end": fin,
            "namespace": namespace.group(1).decode("latin1"),
            "count": int(count.group(1)),
            "payload": payload,
        })

    return resultat


def parse_chaines(payload):
    """
    Analyse et extrait chaines.
    
    Paramètres:
        payload.
    
    Connexions:
        Appelée par : choisir_bloc, choisir_bloc_structurel, construire_appinit_673, construire_payload_compact_fixe, construire_payload_fr_complet, corriger_payload, detecter_langues_ps2, finaliser_textes_pc_specifiques, identifier_langue_bloc_texte, patch_textes_menus_fr, score_francais_bloc, traduire_jam_sans_deplacement.
        Appelle : aucune autre fonction interne directe détectée.
    """
    return {
        match.group(2).decode("latin1"): match.group(4)
        for match in ENTRY.finditer(payload)
    }


def score_langue(valeurs, langue=None):
    """
    Calcule le score de langue.
    
    Paramètres:
        valeurs, langue.
    
    Connexions:
        Appelée par : choisir_bloc, construire_memoire_jam_globale, detecter_langues_ps2, identifier_langue_bloc_texte, score_francais, traduire_jam_sans_deplacement, traduire_tous_jam_localises.
        Appelle : aucune autre fonction interne directe détectée.
    """

    langue = (langue or LANGUE_CIBLE).lower()

    profil = PROFILS_LANGUES.get(langue, PROFILS_LANGUES["fr"])

    score = 0

    for raw in valeurs.values():

        texte = raw.decode("cp1252", errors="ignore").lower()

        score += sum(texte.count(mot) * 3 for mot in profil["mots"])

        score += sum(texte.count(accent) * 2 for accent in profil["accents"])

    return score


def score_francais(valeurs):
    """
    Calcule le score de francais.
    
    Paramètres:
        valeurs.
    
    Connexions:
        Appelée par : score_francais_bloc.
        Appelle : score_langue.
    """

    return score_langue(valeurs, "fr")


def adapter_fr(raw):
    """
    Implémente le traitement interne `adapter_fr` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        raw.
    
    Connexions:
        Appelée par : choisir_traduction_globale, construire_appinit_673, construire_memoire_jam_globale, construire_payload_compact_fixe, construire_payload_fr_complet.
        Appelle : aucune autre fonction interne directe détectée.
    """
    sortie = bytearray()

    for valeur in raw:

        if valeur in GLYPH:

            sortie.append(GLYPH[valeur])

        elif valeur in ACCENT:

            sortie.extend(ACCENT[valeur])

        else:

            sortie.append(valeur)

    resultat = bytes(sortie)

    return resultat


def source_ps2_index():
    """
    Implémente le traitement interne `source_ps2_index` utilisé par le pipeline de localisation ou de diagnostic.
    
    Connexions:
        Appelée par : traduire_tous_jam_localises.
        Appelle : aucune autre fonction interne directe détectée.
    """
    jam_root = (PS2_VERSION / "Data" / "JamFiles")

    resultat = {}

    if not jam_root.exists():
        return resultat

    for fichier in jam_root.rglob("*"):

        if (not fichier.is_file() or fichier.suffix.lower() != ".jam"):
            continue

        rel = str(fichier.relative_to(jam_root)).replace("\\", "/").lower()

        morceaux = rel.split("/")

        if morceaux[0] in ("pc", "ps2"):

            rel = "/".join(morceaux[1:])

        resultat.setdefault(rel, []).append(fichier)

        resultat.setdefault(fichier.name.lower(), []).append(fichier)

    return resultat


def trouver_ps2_jam(pc_rel, index):
    """
    Implémente le traitement interne `trouver_ps2_jam` utilisé par le pipeline de localisation ou de diagnostic.
    
    Paramètres:
        pc_rel, index.
    
    Connexions:
        Appelée par : construire_memoire_jam_globale, traduire_appinit, traduire_autres_jam, traduire_tous_jam_localises.
        Appelle : aucune autre fonction interne directe détectée.
    """
    cle = str(pc_rel).replace("\\", "/").lower()

    candidats = index.get(cle, [])

    if len(candidats) == 1:
        return candidats[0]

    candidats = index.get(Path(pc_rel).name.lower(), [])

    uniques = list(dict.fromkeys(candidats))

    if len(uniques) == 1:
        return uniques[0]

    return None


def choisir_bloc(pc_payload, candidats):
    """
    Sélectionne bloc.
    
    Paramètres:
        pc_payload, candidats.
    
    Connexions:
        Appelée par : traduire_autres_jam.
        Appelle : parse_chaines, score_langue.
    """
    pc_keys = set(parse_chaines(pc_payload))

    meilleur = None
    meilleur_score = None

    for candidat in candidats:

        valeurs = parse_chaines(candidat["payload"])

        overlap = len(pc_keys & set(valeurs))

        if not overlap:
            continue

        score = (
            overlap / max(1, len(pc_keys)),
            score_langue(valeurs),
            overlap,
        )

        if (meilleur_score is None or score > meilleur_score):

            meilleur_score = score
            meilleur = candidat

    return meilleur


