_CACHE_SHA256_FICHIERS = {}


def empreinte_sha256(fichier, data=None):
    """
    Calcule l'empreinte sha256.
    
    Paramètres:
        fichier, data.
    
    Connexions:
        Appelée par : analyser_fichier_complet, analyser_jam_detaille, diagnostiquer_localisation_ps2, diagnostiquer_videos_audio, extraire_entrees_textes_jam.
        Appelle : sha256.
    """
    import hashlib

    fichier = Path(fichier)

    try:
        informations = fichier.stat()
        cle_cache = (
            str(fichier.resolve()),
            informations.st_size,
            informations.st_mtime_ns,
        )
    except OSError:
        cle_cache = (
            str(fichier.absolute()),
            len(data) if data is not None else None,
            None,
        )

    empreinte = _CACHE_SHA256_FICHIERS.get(cle_cache)

    if empreinte is not None:
        return empreinte

    calcul = hashlib.sha256()

    if data is not None:
        calcul.update(data)
    else:
        with fichier.open("rb") as flux:

            while True:

                bloc = flux.read(1024 * 1024)

                if not bloc:
                    break

                calcul.update(bloc)

    empreinte = calcul.hexdigest()
    _CACHE_SHA256_FICHIERS[cle_cache] = empreinte

    return empreinte


def extraire_entrees_textes_jam(fichier, racine, plateforme, data=None):
    """
    Extrait entrees textes JAM.
    
    Paramètres:
        fichier, racine, plateforme, data.
    
    Connexions:
        Appelée par : analyser_jam_detaille, diagnostiquer_cles_textes_pc_ps2.
        Appelle : blocs_texte, empreinte_sha256, identifier_langue_bloc_texte, normaliser_chemin_jam, score_francais_bloc.
    """
    import re

    if data is None:
        data = fichier.read_bytes()

    # Une seule empreinte par JAM. L'ancienne version recalculait le SHA-256
    # intégral à chaque entrée texte, soit plusieurs milliers de lectures du
    # même tampon pour un seul fichier.
    sha256_fichier = empreinte_sha256(fichier, data=data)

    chemin_relatif = str(fichier.relative_to(racine)).replace("\\", "/")

    chemin_normalise = normaliser_chemin_jam(chemin_relatif)

    resultat = []
    occurrences = {}

    for numero_bloc, bloc in enumerate(blocs_texte(data)):

        namespace = bloc["namespace"]

        payload = bloc["payload"]

        score_bloc = score_francais_bloc(payload)

        langue_bloc, scores_langues = (identifier_langue_bloc_texte(payload))

        for numero_entree, match in enumerate(ENTRY.finditer(payload)):

            cle_brute = match.group(2)
            valeur_brute = match.group(4)

            cle = cle_brute.decode("latin1", errors="replace")

            valeur = valeur_brute.decode("cp1252", errors="replace")

            offset_entree = (bloc["begin"] + match.start())

            offset_cle = (bloc["begin"] + match.start(2))

            offset_valeur = (bloc["begin"] + match.start(4))

            variables = re.findall(r"%[A-Za-z]", valeur)

            identifiant_occurrence = (
                namespace,
                cle,
                langue_bloc,
            )

            numero_occurrence = occurrences.get(identifiant_occurrence, 0)

            occurrences[identifiant_occurrence] = numero_occurrence + 1

            resultat.append({
                "plateforme":
                plateforme,
                "fichier":
                chemin_relatif,
                "fichier_normalise":
                chemin_normalise,
                "adresse_fichier":
                str(fichier.resolve()),
                "taille_fichier":
                len(data),
                "sha256_fichier":
                sha256_fichier,
                "chunk_index":
                bloc.get("chunk_index"),
                "offset_bloc_debut":
                bloc["begin"],
                "offset_bloc_debut_hex":
                f"0x{bloc['begin']:X}",
                "offset_bloc_fin":
                bloc["end"],
                "offset_bloc_fin_hex":
                f"0x{bloc['end']:X}",
                "taille_bloc":
                bloc["end"] - bloc["begin"],
                "numero_bloc_texte":
                numero_bloc,
                "score_francais_bloc":
                score_bloc,
                "langue_bloc":
                langue_bloc,
                "scores_langues":
                scores_langues,
                "numero_entree":
                numero_entree,
                "namespace":
                namespace,
                "cle":
                cle,
                "valeur":
                valeur,
                "encodage":
                "cp1252/latin1",
                "longueur_octets":
                len(valeur_brute),
                "numero_occurrence_cle_langue":
                numero_occurrence,
                "offset_entree":
                offset_entree,
                "offset_entree_hex":
                f"0x{offset_entree:X}",
                "offset_cle":
                offset_cle,
                "offset_cle_hex":
                f"0x{offset_cle:X}",
                "offset_valeur":
                offset_valeur,
                "offset_valeur_hex":
                f"0x{offset_valeur:X}",
                "offset_valeur_fin":
                offset_valeur + len(valeur_brute),
                "offset_valeur_fin_hex":
                f"0x{offset_valeur + len(valeur_brute):X}",
                "variables":
                variables,
                "nombre_variables":
                len(variables),
                "identifiant": (f"{chemin_normalise}"
                                f"::{namespace}"
                                f"::{cle}"),
            })

    return resultat


def identifier_langue_bloc_texte(payload):
    """
    Identifie langue bloc texte.
    
    Paramètres:
        payload.
    
    Connexions:
        Appelée par : choisir_bloc_structurel, construire_memoire_jam_globale, diagnostiquer_localisation_ps2, extraire_entrees_textes_jam.
        Appelle : parse_chaines, score_langue.
    """

    valeurs = parse_chaines(payload)

    codes = (
        "fr",
        "en",
        "de",
        "es",
        "it",
    )

    scores = {code: score_langue(valeurs, code) for code in codes}

    classement = sorted(scores.items(),
                        key=lambda element: element[1],
                        reverse=True)

    meilleur_code, meilleur_score = classement[0]
    deuxieme_score = classement[1][1]

    # Une petite banque peut ne contenir aucun mot discriminant.
    langue = (meilleur_code if meilleur_score >= 3
              and meilleur_score > deuxieme_score else "inconnue")

    return langue, scores


