#
#                        DIAGNOSTIQUE COMMPLET
#
##########################################################################################################################################################
##########################################################################################################################################################
##########################################################################################################################################################
##########################################################################################################################################################
##########################################################################################################################################################
###################################################################################################################################
class JournalDiagnostic:
    """Centralise la création et l'alimentation des journaux de diagnostic.

    Les messages sont répartis dans des fichiers spécialisés afin de séparer
    l'exécution, les inventaires, les ressources analysées, les avertissements
    et les plans de reconstruction.
    """

    def __init__(self, dossier):
        """
        Initialise l'état interne de l'instance et prépare ses ressources.
        
        Méthode de la classe `JournalDiagnostic`.
        
        Paramètres:
            self, dossier.
        
        Connexions:
            Appelée par : aucun appel direct statiquement détecté (point d'entrée, callback ou appel dynamique possible).
            Appelle : ecrire.
        """
        from datetime import datetime

        self.dossier = dossier
        self.logs = (dossier / "Logs")

        self.logs.mkdir(parents=True, exist_ok=True)

        self.date_debut = datetime.now()
        self.erreurs = []
        self.avertissements = []

        self.sections = {
            "execution": "00_EXECUTION_COMPLETE.log",
            "environnement": "01_ENVIRONNEMENT.log",
            "pc": "02_INVENTAIRE_PC.log",
            "ps2": "03_INVENTAIRE_PS2.log",
            "comparaison": "04_CORRESPONDANCES_PC_PS2.log",
            "structure": "05_STRUCTURE_DOSSIERS.log",
            "jam": "06_CARTE_BINAIRE_JAM.log",
            "textes": "07_TEXTES.log",
            "polices": "08_POLICES.log",
            "menus": "09_MENUS_INTERFACES.log",
            "images": "10_IMAGES.log",
            "palettes": "11_PALETTES.log",
            "adx": "12_AUDIO_ADX.log",
            "afs": "13_ARCHIVES_AFS.log",
            "sfd": "14_CINEMATIQUES_SFD.log",
            "sous_titres": "15_SOUS_TITRES_DIALOGUES.log",
            "liaisons": "16_LIAISONS_RESSOURCES.log",
            "compatibilite": "17_COMPATIBILITE.log",
            "erreurs": "18_ERREURS_AVERTISSEMENTS.log",
            "injection": "19_PLAN_INJECTION.log",
            "reconstruction": "20_PLAN_RECONSTRUCTION.log",
        }

        for fichier in self.sections.values():

            (self.logs / fichier).write_text("", encoding="utf-8")

        self.ecrire("execution", "DEMARRAGE DU DIAGNOSTIC COMPLET")

    def attention(self, section, message):
        """
        Implémente le traitement interne `attention` utilisé par le pipeline de localisation ou de diagnostic.
        
        Méthode de la classe `JournalDiagnostic`.
        
        Paramètres:
            self, section, message.
        
        Connexions:
            Appelée par : diagnostiquer_cles_textes_pc_ps2, diagnostiquer_jam_pc_ps2, diagnostiquer_jeu_complet, diagnostiquer_localisation_ps2, diagnostiquer_videos_audio, preparer_diagnostic_complet.
            Appelle : ecrire.
        """
        self.ecrire(section, message, "ATTENTION")

    def ecrire(self, section, message, niveau="INFO"):
        """
        Écrit.
        
        Méthode de la classe `JournalDiagnostic`.
        
        Paramètres:
            self, section, message, niveau.
        
        Connexions:
            Appelée par : __init__, attention, diagnostiquer_cles_textes_pc_ps2, diagnostiquer_jam_pc_ps2, diagnostiquer_jeu_complet, diagnostiquer_localisation_ps2, diagnostiquer_menus_interfaces, diagnostiquer_textes_jam, diagnostiquer_videos_audio, entete, erreur, preparer_contexte_diagnostic_cible, preparer_diagnostic_complet, terminer.
            Appelle : aucune autre fonction interne directe détectée.
        """
        from datetime import datetime

        if section not in self.sections:
            section = "execution"

        heure = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        ligne = (f"[{heure}] "
                 f"[{niveau}] "
                 f"{message}")

        print(ligne)

        fichier_section = (self.logs / self.sections[section])

        with fichier_section.open("a", encoding="utf-8") as flux:

            flux.write(ligne + "\n")

        if section != "execution":

            fichier_global = (self.logs / self.sections["execution"])

            with fichier_global.open("a", encoding="utf-8") as flux:

                flux.write(f"[{section.upper()}] "
                           f"{ligne}\n")

        if (niveau == "ERREUR" and section != "erreurs"):

            self.erreurs.append(ligne)

            self.ecrire("erreurs", message, "ERREUR")

        elif (niveau == "ATTENTION" and section != "erreurs"):

            self.avertissements.append(ligne)

            self.ecrire("erreurs", message, "ATTENTION")

    def entete(self, section, titre_section):
        """
        Implémente le traitement interne `entete` utilisé par le pipeline de localisation ou de diagnostic.
        
        Méthode de la classe `JournalDiagnostic`.
        
        Paramètres:
            self, section, titre_section.
        
        Connexions:
            Appelée par : diagnostiquer_cles_textes_pc_ps2, diagnostiquer_jam_pc_ps2, diagnostiquer_jeu_complet, diagnostiquer_menus_interfaces, diagnostiquer_textes_jam, diagnostiquer_videos_audio, preparer_diagnostic_complet, terminer.
            Appelle : ecrire.
        """
        separation = "=" * 70

        self.ecrire(
            section, "\n"
            f"{separation}\n"
            f"{titre_section}\n"
            f"{separation}")

    def erreur(self, section, message):
        """
        Implémente le traitement interne `erreur` utilisé par le pipeline de localisation ou de diagnostic.
        
        Méthode de la classe `JournalDiagnostic`.
        
        Paramètres:
            self, section, message.
        
        Connexions:
            Appelée par : diagnostiquer_cles_textes_pc_ps2, diagnostiquer_jam_pc_ps2, diagnostiquer_jeu_complet, diagnostiquer_menus_interfaces, diagnostiquer_textes_jam, diagnostiquer_videos_audio, preparer_diagnostic_complet.
            Appelle : ecrire.
        """
        self.ecrire(section, message, "ERREUR")

    def terminer(self):
        """
        Finalise.
        
        Méthode de la classe `JournalDiagnostic`.
        
        Paramètres:
            self.
        
        Connexions:
            Appelée par : diagnostiquer_jeu_complet, diagnostiquer_menus_interfaces, diagnostiquer_textes_jam, diagnostiquer_videos_audio.
            Appelle : ecrire, entete.
        """
        from datetime import datetime

        date_fin = datetime.now()

        duree = (date_fin - self.date_debut).total_seconds()

        self.entete("execution", "FIN DU DIAGNOSTIC COMPLET")

        self.ecrire("execution", f"Duree : {duree:.2f} secondes")

        self.ecrire("execution", f"Erreurs : {len(self.erreurs)}")

        self.ecrire("execution", "Avertissements : "
                    f"{len(self.avertissements)}")


SECTOR_SIZE = 2048


class LecteurISO9660:
    def __init__(self, chemin_iso):
        self.chemin_iso = Path(chemin_iso)
        self.fichier = None
        self.racine = None

    def __enter__(self):
        self.fichier = open(self.chemin_iso, "rb")
        self._charger_volume()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.fichier:
            self.fichier.close()

    def _lire_secteur(self, secteur, nombre=1):
        self.fichier.seek(secteur * SECTOR_SIZE)
        return self.fichier.read(SECTOR_SIZE * nombre)

    def _charger_volume(self):
        # Le Primary Volume Descriptor ISO9660 est normalement
        # situé à partir du secteur logique 16.
        secteur = 16

        while True:
            bloc = self._lire_secteur(secteur)

            if len(bloc) < SECTOR_SIZE:
                raise ValueError("ISO9660 invalide.")

            type_volume = bloc[0]
            identifiant = bloc[1:6]

            if identifiant != b"CD001":
                raise ValueError(
                    "Ce fichier ne semble pas etre une ISO ISO9660."
                )

            # Primary Volume Descriptor
            if type_volume == 1:
                self.racine = self._lire_entree(bloc[156:])
                return

            # Volume Descriptor Set Terminator
            if type_volume == 255:
                break

            secteur += 1

        raise ValueError(
            "Primary Volume Descriptor ISO9660 introuvable."
        )

    def _lire_entree(self, donnees):
        longueur = donnees[0]

        if longueur == 0:
            return None

        entree = donnees[:longueur]

        secteur = struct.unpack_from(
            "<I",
            entree,
            2
        )[0]

        taille = struct.unpack_from(
            "<I",
            entree,
            10
        )[0]

        flags = entree[25]

        longueur_nom = entree[32]

        nom_brut = entree[
            33:
            33 + longueur_nom
        ]

        if nom_brut == b"\x00":
            nom = "."
        elif nom_brut == b"\x01":
            nom = ".."
        else:
            nom = nom_brut.decode(
                "ascii",
                errors="replace"
            )

            # ISO9660 ajoute souvent ;1
            if ";" in nom:
                nom = nom.split(";", 1)[0]

        return {
            "nom": nom,
            "secteur": secteur,
            "taille": taille,
            "dossier": bool(flags & 0x02)
        }

    def lister_dossier(self, entree):
        if not entree["dossier"]:
            raise ValueError(
                "L'entree demandee n'est pas un dossier."
            )

        self.fichier.seek(
            entree["secteur"] * SECTOR_SIZE
        )

        donnees = self.fichier.read(
            entree["taille"]
        )

        resultat = []

        position = 0

        while position < len(donnees):
            longueur = donnees[position]

            if longueur == 0:
                # Fin des entrées du secteur courant.
                position = (
                    ((position // SECTOR_SIZE) + 1)
                    * SECTOR_SIZE
                )
                continue

            entree_fichier = self._lire_entree(
                donnees[position:]
            )

            position += longueur

            if not entree_fichier:
                continue

            if entree_fichier["nom"] in (".", ".."):
                continue

            resultat.append(entree_fichier)

        return resultat

    def trouver(self, chemin):
        morceaux = [
            x
            for x in str(chemin)
            .replace("\\", "/")
            .split("/")
            if x
        ]

        courant = self.racine

        for morceau in morceaux:
            trouve = None

            for entree in self.lister_dossier(courant):
                if entree["nom"].casefold() == morceau.casefold():
                    trouve = entree
                    break

            if trouve is None:
                return None

            courant = trouve

        return courant

    def lire_fichier(self, entree):
        if entree["dossier"]:
            raise ValueError(
                "Impossible de lire un dossier comme fichier."
            )

        self.fichier.seek(
            entree["secteur"] * SECTOR_SIZE
        )

        return self.fichier.read(
            entree["taille"]
        )

    def extraire_fichier(
        self,
        entree,
        destination
    ):
        destination = Path(destination)

        destination.parent.mkdir(
            parents=True,
            exist_ok=True
        )

        self.fichier.seek(
            entree["secteur"] * SECTOR_SIZE
        )

        restant = entree["taille"]

        with open(destination, "wb") as sortie:
            while restant > 0:
                bloc = self.fichier.read(
                    min(
                        1024 * 1024,
                        restant
                    )
                )

                if not bloc:
                    raise IOError(
                        "Fin inattendue de l'ISO."
                    )

                sortie.write(bloc)
                restant -= len(bloc)

    def extraire_dossier(
        self,
        entree,
        destination
    ):
        destination = Path(destination)

        destination.mkdir(
            parents=True,
            exist_ok=True
        )

        for element in self.lister_dossier(entree):
            cible = destination / element["nom"]

            if element["dossier"]:
                self.extraire_dossier(
                    element,
                    cible
                )
            else:
                self.extraire_fichier(
                    element,
                    cible
                )

    def detecter_version_ps2(self):
        for entree in self.lister_dossier(
            self.racine
        ):
            nom = entree["nom"].upper()

            if nom.startswith("SLES_526."):
                return nom

        return None


def demander_iso_ps2():
    """
    Ouvre une fenêtre Windows permettant de sélectionner une ISO PS2.

    Retourne :
        Path(...) si une ISO est sélectionnée.
        None si l'utilisateur clique sur Annuler.
    """

    root = tk.Tk()
    root.withdraw()

    # Place la boîte de dialogue devant les autres fenêtres.
    root.attributes("-topmost", True)

    fichier = filedialog.askopenfilename(
        title="Sélectionner l'ISO PS2 de Leisure Suit Larry",
        filetypes=[
            ("Image disque ISO", "*.iso"),
            ("Tous les fichiers", "*.*"),
        ],
    )

    root.destroy()

    if not fichier:
        return None

    return Path(fichier)


